const h=[{id:"vb05-1",s:"",cc:"Khoản 1 Điều 1 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp và là cơ quan chấp hành của Quốc hội; cơ quan quyền lực nhà nước cao nhất là Quốc hội.",mn:'Nhớ "hành chính cao nhất - hành pháp - chấp hành của Quốc hội": giống người điều hành công việc hằng ngày theo nghị quyết của cơ quan đã giao việc.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi xác định vị trí, chức năng của Chính phủ trong bộ máy nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam, cách xác định nào dưới đây phản ánh đúng quy định của Luật?",o:["Là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp và là cơ quan chấp hành của Quốc hội","Là cơ quan quyền lực nhà nước cao nhất, thực hiện quyền hành pháp và là cơ quan chấp hành của Quốc hội","Là cơ quan hành chính nhà nước cao nhất, thực hiện quyền lập pháp và là cơ quan chấp hành của Quốc hội","Là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp và là cơ quan chấp hành của Chủ tịch nước"],c:0},{id:"vb05-2",s:"",cc:"khoản 2 Điều 1 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ chịu trách nhiệm trước Quốc hội và báo cáo công tác trước Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước; các cơ quan tư pháp không thuộc nhóm nhận báo cáo này.",mn:'Nhớ "ba nơi nhận báo cáo”: Quốc hội — Ủy ban Thường vụ — Chủ tịch nước, như báo cáo công việc với ba cấp có thẩm quyền theo dõi.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), ngoài việc chịu trách nhiệm trước Quốc hội, Chính phủ còn có nghĩa vụ báo cáo công tác trước nhóm cơ quan, người đứng đầu nào dưới đây trong bộ máy nhà nước?",o:["Quốc hội, Chủ tịch nước và Tòa án nhân dân tối cao","Quốc hội, Ủy ban Thường vụ Quốc hội và Chủ tịch nước","Quốc hội, Ủy ban Thường vụ Quốc hội và Viện kiểm sát nhân dân tối cao","Ủy ban Thường vụ Quốc hội, Chủ tịch nước và Hội đồng Dân tộc"],c:1},{id:"vb05-3",s:"",cc:"Khoản 1 Điều 2 Luật Tổ chức Chính phủ năm 2025.",gt:'Thành viên Chính phủ gồm Thủ tướng, các Phó Thủ tướng, các Bộ trưởng và Thủ trưởng cơ quan ngang Bộ: Thủ trưởng cơ quan thuộc Chính phủ không phải là thành viên Chính phủ. ® Miẹo nhớ: Nhớ "Bộ trưởng đi cùng Thủ trưởng cơ quan ngang Bộ”: hai chức danh đứng cùng hàng trong Chính phủ, còn cơ quan thuộc Chính phủ chỉ được mời họp khi cần.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13): Chính phủ gồm Thủ tướng Chính phủ, các Phó Thủ tướng Chính phủ, các Bộ trưởng và [........ ], còn cơ cấu số lượng thành viên Chính phủ do Thủ tướng Chính phủ trình Quốc hội quyết định.",o:["Thủ trưởng cơ quan ngang Bộ","Thủ trưởng cơ quan thuộc Chính phủ","Chủ tịch Ủy ban nhân dân cấp tỉnh","Người đứng đầu cơ quan chuyên môn"],c:0},{id:"vb05-4",s:"",cc:"Khoản 1 Điều 2 Luật TỔ chức Chính phủ năm 2025.",gt:'Thủ tướng Chính phủ trình, Quốc hội quyết định cơ cấu số lượng thành viên Chính phủ. $® Miẹo nhớ: Nhớ "Thủ tướng trình - Quốc hội quyết”: người đứng đầu đề xuất, cơ quan quyền lực cao nhất chốt.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), hãy xác định đúng chủ thể trình và cơ quan quyết định đối với cơ cấu số lượng thành viên Chính phủ, trong mối quan hệ giữa người đứng đầu Chính phủ và cơ quan quyền lực nhà nước cao nhất?",o:["Thủ tướng Chính phủ trình, Quốc hội quyết định","Chủ tịch nước trình theo đề nghị của Thủ tướng Chính phủ, Ủy ban Thường vụ Quốc hội xem xét và quyết định sau khi lấy ý kiến của các Bộ trưởng","Chính phủ tự quyết định, báo cáo Quốc hội","Ủy ban Thường vụ Quốc hội trình, Quốc hội quyết định"],c:0},{id:"vb05-5",s:"",cc:"Khoản 2 Điều 2 Luật Tổ chức Chính phù năm 2025.",gt:"Cơ cấu tổ chức của Chính phủ gồm các Bộ, cơ quan ngang Bộ: việc thành lập, bãi bỏ do Chính phủ trình Quốc hội quyết định. Cơ quan thuộc Chính phủ do Chính phủ quyết định thành lập. không năm trong cơ cấu này.",mn:'Nhớ "Bỏ - cơ quan ngang Bộ, Quốc hội quyết”: đơn vị lớn của Chính phủ muốn lập hay bộ phải qua Quốc hội.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), về cơ cấu tổ chức của Chính phủ và thẩm quyền đối với việc thành lập, bãi bỏ các cơ quan trong cơ cấu đó, nhận định nào dưới đây phản ánh đúng quy định của Luật?",o:["Cơ cấu gồm các Bộ, cơ quan ngang Bộ; việc thành lập, bãi bỏ do Chính phủ trình Ủy ban Thường vụ Quốc hội quyết định","Cơ cấu gồm các Bộ, cơ quan thuộc Chính phủ; việc thành lập, bãi bỏ do Chính phủ trình Quốc hội quyết định","Cơ cấu gồm các Bộ, cơ quan ngang Bộ; việc thành lập, bãi bỏ do Thủ tướng Chính phủ trình Chủ tịch nước quyết định","Cơ cấu gồm các Bộ, cơ quan ngang Bộ; việc thành lập, bãi bỏ do Chính phủ trình Quốc hội quyết định"],c:3},{id:"vb05-6",s:"",cc:"Điều 3 Luật Tổ chức Chính phủ năm 2025,",gt:"Chính phủ tiếp tục làm nhiệm vụ cho đến khi Quốc hội khóa mới thành lập Chính phủ, bảo đảm hoạt động không bị gián đoạn; việc bầu Thủ tướng chỉ là một bước trong quá trình độ.",mn:'Nhớ "chưa có Chính phủ mới thì Chính phủ cũ còn làm việc”: như người giữ việc cho đến khi có người nhận bàn giao.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Nhiệm kỳ của Chính phủ theo nhiệm kỳ của Quốc hội. Khi Quốc hội hết nhiệm kỳ, Chính phủ tiếp tục làm nhiệm vụ cho đến khi [........ L",o:["Quốc hội khóa mới bầu Thủ tướng Chính phủ","Chủ tịch nước mới được bầu hoặc bổ nhiệm","Quốc hội khóa mới thành lập Chính phủ","Thủ tướng Chính phủ mời nhậm chức"],c:2},{id:"vb05-7",s:"",cc:"Khoôn Ì Điều 4 Luật Tổ chức Chính phủ năm 2023.",gt:"Thủ tướng Chính phủ do Quốc hội bầu trong số các đại biểu Quốc hội theo đề nghị của Chủ tịch nước.",mn:'Nhớ "đại biểu Quốc hội - Chủ tịch nước đề nghị”: người được chọn phải là đại biểu, người giới thiệu là Chủ tịch nước.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi bầu người đứng đầu Chính phủ, Quốc hội thực hiện việc bầu trong số những ai và căn cứ vào đề nghị của chủ thể nào?",o:["Đại biểu Quốc hội; đề nghị của Chính phủ","Thành viên Chính phủ; đề nghị của Chủ tịch nước","Đại biểu Quốc hội; đề nghị của Chủ tịch nước","Đại biểu Quốc hội; đề nghị của Chủ tịch Quốc hội"],c:2},{id:"vb05-8",s:"",cc:"Khoản 2 Điều 4 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng Chính phủ là người đứng đầu Chính phủ và hệ thống hành chính nhà nước; Thủ tướng không đứng đầu Nhà nước hay Quốc hội.",mn:'Nhớ "đứng đầu Chính phủ và hệ thống hành chính": phạm vi chỉ là nhánh hành pháp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), quy định về Thủ tướng Chính phủ xác định Thủ tướng giữ vai trò đứng đầu đối với những thiết chế nào, qua đó phân biệt với vai trò của các thành viên khác của Chính phủ?",o:["Nhà nước, Chính phủ và toàn bộ hệ thống chính trị từ trung ương đến địa phương, bao gồm cả cơ quan lập pháp và cơ quan tư pháp","Chính phủ và hệ thống hành chính nhà nước","Chính phủ và Nhà nước","Hệ thống hành chính nhà nước và Quốc hội"],c:1},{id:"vb05-9",s:"",cc:"Khoản 2 Điều 5 Luật Tổ chức Chính phủ năm 2025.",gt:'Bộ máy hành chính phải tinh gọn, hiệu năng, hiệu lực, hiệu quả; cụm "hiệu năng” là điểm dễ bị bỏ sót.',mn:'Nhớ "tinh gọn + ba chữ hiệu”: hiệu năng, hiệu lực, hiệu quả.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nguyên tắc tổ chức và hoạt động của Chính phủ yêu cầu tổ chức bộ máy hành chính quản lý đa ngành, đa lĩnh vực, [........ ]; bảo đảm cơ quan cấp dưới phục tùng sự lãnh đạo, chỉ đạo của cơ quan cấp trên.",o:["tinh gọn, hiệu năng, hiệu lực, hiệu quả","tinh gọn, hiệu lực, hiệu quả, minh bạch","gọn nhẹ, hiệu năng, hiệu lực, công khai","tinh gọn, hiệu năng, hiệu quả, thống nhất"],c:0},{id:"vb05-10",s:"",cc:"Khoản 4 Điều 5 Luật Tổ chức Chính phủ năm 2025.",gt:'Chính phủ phân quyền, phân cấp hợp lý cho chính quyền địa phương, vừa bảo đảm quản lý thống nhất của Chính phủ vừa phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của địa phương. ® Miẹo nhớ: Nhớ "thống nhất ở trên, chủ động ở dưới": Chính phủ giữ quản lý chung, địa phương tự chịu trách nhiệm phân được giao.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi xác định mối quan hệ giữa Chính phủ với chính quyền địa phương, nguyên tắc tổ chức và hoạt động của Chính phủ đặt ra yêu cầu nào dưới đây?",o:["Phân quyền, phân cấp hợp lý, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của Bộ, cơ quan ngang Bộ","Phân quyền, phân cấp hợp lý, bảo đảm quyền quản lý thống nhất của Quốc hội và phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của chính quyền địa phương","Phân quyền, phân cấp hợp lý, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của chính quyền địa phương","Phân quyền, phân cấp hợp lý, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, sáng tạo, chịu trách nhiệm trước cấp trên trực tiếp"],c:2},{id:"vb05-11",s:"",cc:"Khoản 3 Điều 5 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ thực hiện nguyên tắc tập thể lãnh đạo, cá nhân phụ trách, đề cao trách nhiệm cá nhân của người đứng đầu; không thay trách nhiệm cá nhân băng trách nhiệm tập thể.",mn:'Nhớ "tập thể bản, cá nhân chịu": quyết định chung nhưng mọi người đứng đầu văn chịu trách nhiệm phân mình.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong tổ chức và hoạt động, Chính phủ phải phân định rõ nhiệm vụ, quyền hạn, trách nhiệm giữa Chính phủ, Thủ tướng Chính phủ với Bộ trưởng, đồng thời báo đảm nguyên tắc nào về cách thức lãnh đạo, điều hành?",o:["Tập trung dân chủ, cá nhân quyết định","Thủ trưởng quyết định, tập thể tham gia ý kiến","Tập thể lãnh đạo, cá nhân phụ trách","Tập thể lãnh đạo, cá nhân phụ trách, đề cao trách nhiệm tập thể thay cho trách nhiệm cá nhân của người đứng đầu các cơ quan hành chính"],c:2},{id:"vb05-12",s:"",cc:"Khoản 1 Điều 5, khoản 3 Điều 6 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ hướng dẫn chính quyền địa phương; địa phương chủ động quyết định, tổ chức thực hiện và chịu trách nhiệm về nhiệm vụ được phân quyền, nền Chính phủ không quyết định thay.",mn:'Nhớ "việc đã phân quyền thì địa phương tự làm, tự chịu”: cấp trên hướng dẫn chủ không làm thay.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong các nội dung dưới đây về nguyên tắc tổ chức và hoạt động của Chính phủ, nội dung nào KHÔNG phù hợp với quy định của Luật?",o:["Thực hiện nguyên tắc tập trung dân chủ, quản lý xã hội bằng Hiến pháp và pháp luật, bảo đảm bình đẳng giới trong tổ chức và hoạt động","Chính phủ quyết định thay chính quyền địa phương mọi vấn đề thuộc nhiệm vụ, quyền hạn đã được phân quyền cho địa phương","Phân định rõ nhiệm vụ, quyền hạn, trách nhiệm giữa Chính phủ, Thủ tướng Chính phủ với Bộ trưởng, Thủ trưởng cơ quan ngang Bộ","Xây dựng nền hành chính thống nhất, thông suốt, liên tục, dân chủ, pháp quyền, chuyên nghiệp, hiện đại, công khai, minh bạch"],c:1},{id:"vb05-13",s:"",cc:"Khoản 5 Điều G1 Luật Tổ chức Chính phủ nam 2035,",gt:"Thủ tướng không quyết định các vấn đề thuộc thẩm quyền, trách nhiệm của Bộ trưởng đối với ngành, lĩnh vực được phân công: trường hợp cần thiết thì chỉ đạo, điều hành việc giải quyết.",mn:'Nhớ "không làm thay, cần thì chỉ đạo”: như người quản lý không làm việc của nhân viên nhưng vẫn điều phối khi có vướng.',t:"m",q:"Trường hợp Bộ trưởng Bộ X chịu trách nhiệm quản lý một ngành, lĩnh vực theo phân công của Chính phủ. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ có quyết định thay các vấn đề thuộc thẩm quyền và trách nhiệm của Bộ trưởng đối với ngành, lĩnh vực do hay không, theo nguyên tắc phân định thẩm quyền?",o:["Không quyết định thay; khi cần thiết thì chỉ đạo, điều hành việc giải quyết","Được quyết định thay trong mọi trường hợp","Chỉ quyết định thay khi Bộ trưởng có đề nghị","Được quyết định thay đối với mọi vấn đề thuộc ngành, lĩnh vực do, vì Thủ tướng Chính phủ là người đứng đầu Chính phủ và lãnh đạo công tác của Chính phủ"],c:0},{id:"vb05-14",s:"",cc:"khoản 2 Điều © Luật TỔ chức Chính phủ năm 2ZU3a,",gt:"Yêu cầu khi phân quyền, phân cấp gồm rõ chủ thể. nội dung, phạm vi; công khai, minh bạch, trách nhiệm giải trình; giám sát, thanh tra, kiểm tra, kiểm soát quyền lực.",mn:'Nhớ "công khai — minh bạch - giải trình”: giao việc phải rõ ràng và giải thích được.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), việc phân quyền, phân cấp phải báo đảm rõ chủ thể, nội dung, phạm vi nhiệm vụ, quyền hạn, công khai, minh bạch, [........ ], giám sát, thanh tra, kiểm tra, kiểm soát quyền lực theo quy định của Hiến pháp và pháp luật.",o:["trách nhiệm giải trình","trách nhiệm bồi thường","trách nhiệm liên đới","trách nhiệm báo cáo"],c:0},{id:"vb05-15",s:"",cc:"Khoản Ì Điều 7 Luật Tổ chức Chính phủ năm 2025.",gt:"Phân quyền là việc Quốc hội quy định nhiệm vụ, quyền hạn trong luật, nghị quyết; không phải việc Chính phủ quy định trong nghị định hay giao có thời hạn như ủy quyền.",mn:'Nhớ "phân quyền = Quốc hội quy định bằng luật, nghị quyết”: nguồn phân quyền là cơ quan lập pháp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), phân biệt với phân cấp và ủy quyền, khái niệm phân quyền trong hệ thống cơ quan nhà nước được hiểu là việc nào dưới đây?",o:["Chính phủ quy định nhiệm vụ, quyền hạn trong nghị định",'Quốc hội giao thực hiện trong khoảng thời gian xác định Luật fCC.P "U25 Trang b',"Quốc hội quy định nhiệm vụ, quyền hạn của cơ quan, tổ chức, cá nhân trong pháp lệnh, nghị quyết, bảo đảm phù hợp nguyên tắc phân định thẩm quyền","Quốc hội quy định nhiệm vụ, quyền hạn trong luật, nghị quyết"],c:3},{id:"vb05-16",s:"",cc:"khoan Ì Điều 8 Luật Tổ chức Chính phủ năm 2025.",gt:"Phân cấp: giao thực hiện liên tục, thường xuyên, việc phân cấp phải được quy định trong văn bản quy phạm pháp luật; bên được phân cấp chịu trách nhiệm hoàn toàn về kết quả.",mn:'Nhớ "phân cấp = thường xuyên + văn bản quy phạm": giao lâu dài thì phải có văn bản quy phạm.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khái niệm phân cấp trong hệ thống cơ quan nhà nước có đặc điểm nổi bật nào về tính liên tục của việc giao và hình thức văn bản?",o:["Giao thực hiện liên tục, thường xuyên và được quy định trong văn bản quy phạm pháp luật","Giao thực hiện trong khoảng thời gian xác định và được thể hiện bằng văn bản ủy quyền","Giao thực hiện một lần và được thể hiện bằng văn bản hành chính","Giao thực hiện liên tục, thường xuyên, thể hiện trong văn bản của người phân cấp và chuyển toàn bộ trách nhiệm về kết quả cho cơ quan cấp trên đã phân cấp"],c:0},{id:"vb05-17",s:"",cc:"Khoản 1 Điều 9 Luật Tổ chức Chính phủ năm 2025.",gt:"Ủy quyền: giao thực hiện trong khoảng thời gian xác định, người ủy quyền chịu trách nhiệm về kết quả, thể hiện trong văn bản của người ủy quyền (không phải văn bản quy phạm pháp luật).",mn:'Nhớ "ủy quyền = có thời hạn, người giao chịu trách nhiệm”: như giấy ủy quyền có ngày hết hạn.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khái niệm ủy quyền trong hệ thống cơ quan nhà nước được xác định như thế nào, xét về thời gian thực hiện, trách nhiệm về kết quả và hình thức thể hiện?",o:["Giao thực hiện trong khoảng thời gian xác định một hoặc một số nhiệm vụ, quyền hạn, người ủy quyền chịu trách nhiệm về kết quả, thể hiện trong văn bản","Giao thực hiện liên tục, thường xuyên một hoặc một số nhiệm vụ, quyền hạn, người ủy quyền chịu trách nhiệm về kết quả, thể hiện trong văn bản","Giao thực hiện trong khoảng thời gian xác định một hoặc một số nhiệm vụ, quyền hạn, người được ủy quyền chịu trách nhiệm hoàn toàn về kết quả, thể hiện trong văn bản",'Giao thực hiện trong khoảng thời gian xác định một hoặc một số nhiệm vụ, quyền hạn, người ủy quyền chịu trách nhiệm về kết quả, thể hiện trong văn bản quy phạm pháp luật Luậi fCCP "U25 Trang -'],c:0},{id:"vb05-18",s:"",cc:"Khoản 1 Điều 8 và khoản 1 Điều 9 Luật TỔ chức Chính phủ năm 2025.",gt:"Phân cấp giao liên tục, thường xuyên (văn bản quy phạm pháp luật): ủy quyền giao trong khoảng thời gian xác định (vấn ban của người ủy quyền).",mn:'Nhớ "phân cấp thường xuyên - ủy quyền có thời hạn”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), điểm khác biệt cơ bản giữa phân cấp và ủy quyền trong hệ thống cơ quan nhà nước được xác định như thế nào?",o:["Phân cấp là giao thực hiện trong khoảng thời gian xác định; ủy quyền là giao thực hiện liên tục, thường xuyên","Phân cấp thể hiện bằng văn bản của người ủy quyền; ủy quyền phải quy định trong văn bản quy phạm pháp luật","Phân cấp là giao thực hiện liên tục, thường xuyên; ủy quyền là giao thực hiện trong khoảng thời gian xác định","Phân cấp do Quốc hội quy định trong luật; ủy quyền là giao thực hiện trong khoảng thời gian xác định"],c:2},{id:"vb05-19",s:"",cc:"Khoản 5 Điều 8 Luật Tổ chức Chính phù nam 2025.",gt:"Cơ quan được phân cấp không được phân cấp tiếp nhiệm vụ, quyền hạn mà mình được phân cấp; không có ngoại lệ do cấp trên đồng ý hay luật chuyên ngành.",mn:'Nhớ "được phân cấp thì giữ, không chuyển tiếp”.',t:"m",q:"Trường hợp Ủy ban nhân dân tỉnh Y được Bộ trưởng Bộ X phân cấp thực hiện thường xuyên một nhiệm vụ. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Ủy ban nhân dân tỉnh Ý có được phân cấp tiếp nhiệm vụ đó cho cơ quan chuyên môn hay không, và căn cứ vào đầu?",o:["Được phân cấp tiếp, vì Ủy ban nhân dân cấp tính là cấp chính quyền địa phương có quyền chủ động trong nhiệm vụ được phân cấp","Không được phân cấp tiếp, vì cơ quan được phân cấp không được phân cấp tiếp nhiệm vụ, quyền hạn mà mình được phân cấp","Được phân cấp tiếp, nếu được cơ quan phân cấp ban đầu đồng ý bằng văn bản và bảo đảm đủ điều kiện thực hiện","Không được phân cấp tiếp, trừ khi pháp luật chuyên ngành có quy định khác về việc phân cấp tiếp nhiệm vụ đó"],c:1},{id:"vb05-20",s:"",cc:"Khoản 6 Điều 9 Luật Tổ chức Chính phủ năm 2025.",gt:'Cơ quan, cá nhân được ủy quyền không được ủy quyền tiếp nhiệm vụ, quyền hạn mà mình được ủy quyền, kể cả khi người ủy quyền đồng ý. ® Miẹo nhớ: Nhớ "được ủy quyền thì từ làm, không ủy quyền lại".',t:"m",q:"Trường hợp Chủ tịch Ủy ban nhân dân tỉnh Y được Thủ tướng Chính phủ ủy quyền thực hiện một nhiệm vụ trong 12 tháng, nay muốn ủy quyền tiếp cho Giám đốc Sở. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), việc ủy quyền tiếp này được xử lý theo hướng nào?",o:["Được, nếu Thủ tướng Chính phủ đồng ý","Được ủy quyền tiếp cho cấp dưới trực tiếp","Được, nhưng phải báo cáo người ủy quyền","Không được ủy quyền tiếp"],c:3},{id:"vb05-21",s:"",cc:"Khoản 2 Điều 8 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ, Thủ tướng phân cấp cho Bộ trưởng, Thủ trưởng cơ quan ngang Bộ (với tư cách người đứng đầu Bộ), Thủ trưởng cơ quan thuộc Chính phủ, HĐND, UBND, Chủ tịch UBND; việc phân cấp cho tổ chức, đơn vị trực thuộc Bộ là của Bộ trưởng.",mn:'Nhớ "Chính phủ phân cấp xuống Bộ, cơ quan thuộc Chính phủ và địa phương: đơn vị trực thuộc Bộ do Bộ trưởng phân cấp”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ, Thủ tướng Chính phủ thực hiện phân cấp cho những chủ thể nào dưới đây, trừ trường hợp pháp luật quy định không được phân cấp?",o:["Bộ trưởng, Thủ trưởng cơ quan ngang Bộ với tư cách người đứng đầu Bộ; Thủ trưởng cơ quan thuộc Chính phủ; Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân và tổ chức, đơn vị trực thuộc Bộ","Bộ trưởng, Thủ trưởng cơ quan ngang Bộ với tư cách người đứng đầu Bộ; Thủ trưởng cơ quan thuộc Chính phủ; Hội đồng nhân dân, Ủy ban nhân dân (không gồm Chủ tịch Ủy ban nhân dân)","Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ; Thủ trưởng cơ quan thuộc Chính phủ; Hội đồng nhân dân, Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân","Bộ trưởng, Thủ trưởng cơ quan ngang Bộ với tư cách người đứng đầu Bộ; Thủ trưởng cơ quan thuộc Chính phủ; Hội đồng nhân dân, Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân"],c:3},{id:"vb05-22",s:"",cc:"Khoản ở Điều 9 Luật Tổ chức Chính phủ năm 2025,",gt:"Thủ tướng ủy quyền cho Bộ trưởng, Thủ trưởng cơ quan ngang Bộ, Thủ trưởng cơ quan thuộc Chính phủ, UBND cấp tỉnh, Chủ tịch UBND cấp tỉnh; Giám đốc Sở không thuộc nhóm này.",mn:'Nhớ "Thủ tướng ủy quyền đến cấp tính là dừng”: không xuống đến Giám đốc SỞ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ ủy quyền cho nhiều chủ thể trong hệ thống hành chính nhà nước; chủ thể nào dưới đây KHÔNG thuộc nhóm được Thủ tướng Chính phủ ủy quyền?",o:["Giám đốc Sở thuộc Ủy ban nhân dân tỉnh","Thủ trưởng cơ quan thuộc Chính phủ","Ủy ban nhân dân cấp tỉnh","Thủ trưởng cơ quan ngang Bộ"],c:0},{id:"vb05-23",s:"",cc:"Điểm a khoản 3 Điều 9 Luật TỔ chức Chính phù năm 2025,",gt:"Văn bản ủy quyền phải ghi cụ thể nội dung, phạm vi, thời hạn, cách thức thực hiện và điều kiện cần thiết; thời hạn là vếu tổ phân biệt ủy quyền với phân cấp.",mn:'Nhớ "nội dung - phạm vi - thời hạn”: giấy ủy quyền nào cũng phải ghi việc gì, đến đầu, đến khi nào.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), văn bản ủy quyền phải quy định cụ thể nội dung, phạm vi và [........ ] ủy quyền, cách thức thực hiện ủy quyền cùng các điều kiện cần thiết khác để thực hiện nhiệm vụ, quyền hạn được ủy quyền.",o:["hiệu lực","kinh phí","mục đích","thời hạn"],c:3},{id:"vb05-24",s:"",cc:'Khoản 4 và khoản 5 Điều 9 Luật TỔ chức Chính phủ năm 2025, Luut TCCP "25 lrong IU',gt:"Nếu thực hiện không đúng nội dung, phạm vi, thời hạn ủy quyền thì bên được ủy quyền chịu trách nhiệm trước pháp luật, người ủy quyền không phải chịu trách nhiệm về phân thực hiện sai đó.",mn:'Nhớ "làm sai ủy quyền thì người nhận tự chịu”.',t:"m",q:"Trường hợp Bộ trưởng Bộ X ủy quyền cho Chủ tịch Ủy ban nhân dân tỉnh Y thực hiện một nhiệm vụ, nhưng Chủ tịch Ủy ban nhân dân tỉnh Y thực hiện vượt quá phạm vi đã ủy quyền và gây thiệt hại. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trách nhiệm về việc thực hiện không đúng đó được xác định như thế nào?",o:["Bên được ủy quyền chịu trách nhiệm trước pháp luật về phân thực hiện sai","Người ủy quyền chịu toàn bộ trách nhiệm","Hai bên cùng chịu trách nhiệm ngang nhau","Người ủy quyền và người được ủy quyền cùng chịu trách nhiệm liên đổi về toàn bộ kết quả, vì người ủy quyền chịu trách nhiệm về tính hợp pháp của việc ủy quyền"],c:0},{id:"vb05-25",s:"",cc:"Khoản 4 Điều 8 Luật Tổ chức Chính phủ năm 2025.",gt:"Người phân cấp phải theo dõi, hướng dẫn, kiểm tra và chỉ chịu trách nhiệm về kết quả khi không bảo đảm điều kiện thực hiện; bên được phân cấp chịu trách nhiệm hoàn toàn về kết quả.",mn:'Nhớ "giao việc phải theo dõi, thiếu điều kiện thì chịu trách nhiệm”.',t:"m",q:"Trường hợp Bộ trưởng Bộ X đã quyết định phân cấp một nhiệm vụ cho Ủy ban nhân dân tỉnh Ý. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), cơ quan phân cấp có trách nhiệm nào dưới đây đối với nhiệm vụ đã phân cấp?",o:["Theo dõi, hướng dẫn, kiểm tra việc thực hiện để bảo đảm hiệu lực, hiệu quả; chịu trách nhiệm hoàn toàn về kết quả thực hiện nhiệm vụ đã phân cấp","Theo dõi, hướng dẫn, kiểm tra việc thực hiện để bảo đảm hiệu lực, hiệu quả; chịu trách nhiệm về kết quả nếu không bảo đảm điều kiện","Chỉ hướng dẫn khi được đề nghị, không kiểm tra; chịu trách nhiệm về kết quả nếu không bảo đảm điều kiện thực hiện nhiệm vụ","Theo dõi, hướng dẫn, kiểm tra việc thực hiện đề bảo đảm hiệu lực, hiệu quả; không chịu trách nhiệm về kết quả trong mọi trường hợp"],c:1},{id:"vb05-26",s:"",cc:"Khoản 5 Điều 6 Luật Tổ chức Chính phủ năm 2025.",gt:"Trường hợp cần thiết, Chính phủ, Thủ tướng chỉ đạo, điều hành việc giải quyết vấn đề thuộc nhiệm vụ của Bộ trưởng, chính quyền địa phương; không quyết định thay hay thu hội phân quyền.",mn:'Nhớ "cần thiết thì chỉ đạo, điều hành” chứ không làm thay.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), một vấn đề thuộc nhiệm vụ, quyền hạn của chính quyền địa phương kéo dài chưa được giải quyết. Trường hợp cần thiết, Chính phủ, Thủ tướng Chính phủ có thể thực hiện việc nào dưới đây theo nguyên tắc phân định thẩm quyền?",o:["Chỉ đạo, điều hành việc giải quyết vấn đề đó","Thu hồi toàn bộ nhiệm vụ đã phân quyền","Chuyến vấn đề sang Quốc hội quyết định","Trực tiếp quyết định thay chính quyền địa phương đối với mọi vấn đề được phân quyền, vì Chính phủ có quyền quản lý thống nhất các ngành, lĩnh vực"],c:0},{id:"vb05-27",s:"",cc:"Khoản 1 Điều 6 Luật Tổ chức Chính phù năm 2025.",gt:"Chính phủ trình các nội dung theo Hiến pháp, vấn đề cơ bản, quan trọng của Quốc hội và vấn đề thuộc thẩm quyền của Ủy ban Thường vụ Quốc hội; nhân sự Số không thuộc nhóm này.",mn:'Nhớ "trình việc lớn của Quốc hội, không trình nhân sự Số”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ có trách nhiệm trình Quốc hội, Ủy ban Thường vụ Quốc hội quyết định Luáạt TCCP 2025 Iruongl1l nhiều nội dung theo nguyên tắc phân định thẩm quyền; nội dung nào dưới đây KHÔNG thuộc phạm vi các nội dung đó?",o:["Các nội dung theo quy định của Hiến pháp thuộc thẩm quyền của Quốc hội","Những vấn đề cơ bản, quan trọng thuộc thẩm quyền của Quốc hội","Việc bổ nhiệm, miễn nhiệm Giám đốc Sở thuộc Ủy ban nhân dân cấp tỉnh trong từng nhiệm kỳ","Các vấn đề thuộc thẩm quyền của Ủy ban Thường vụ Quốc hội quy định tại luật về tổ chức Quốc hội"],c:2},{id:"vb05-28",s:"",cc:"Khoản 9 Điều 6 Luật Tổ chức Chính phủ năm 2025.",gt:"Mục tiêu khuyến khích phân quyền, phân cấp: phát huy tính linh hoạt, sáng tạo, giải phóng nguồn lực, thúc đẩy phát triển kinh tế - xã hội.",mn:'Nhớ "linh hoạt -— sáng tạo - giải phóng nguồn lực”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Luật khuyến khích cơ quan nhà nước ở trung ương và chính quyền địa phương chủ động đề xuất việc phân quyền, phân cấp gắn với cơ chế, chính sách, giải pháp nhằm phát huy tính linh hoạt, sáng tạo, [......... ], thúc đẩy phát triển kinh tế - xã hội.",o:["tiết kiệm nguồn lực","tập trung nguồn lực","huy động nguồn lực","giải phóng nguồn lực"],c:3},{id:"vb05-29",s:"",cc:"Khoản 6 Điều 8 Luật TỔ chức Chính phủ năm 2025. Luáạt TCCP 2025 Irong 12",gt:"Phải giảm thủ tục hành chính, không thêm thành phần hồ sơ, không tăng thêm yêu cầu, điều kiện, thời gian giải quyết; sau đó báo cáo cơ quan nhà nước cấp trên.",mn:'Nhớ "giảm chứ không tăng”: giảm thủ tục, không thêm hồ sơ, không them điều kiện, không thêm thời gian.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi việc phân cấp dẫn đến phải thay đổi trình tự, thủ tục, thẩm quyền đăng quy định trong văn bản của cơ quan nhà nước cấp trên, cơ quan, người phân cấp được điều chỉnh nhưng phải bảo đảm yêu cầu cải cách hành chính nào?",o:["Giữ nguyên thủ tục; không thêm hồ sơ, yêu cầu, điều kiện","Giảm thủ tục; được thêm hồ sơ khi cần thiết","Giảm thủ tục; không thêm hồ sơ, yêu cầu, điều kiện, thời gian giải quyết","Giảm thủ tục hành chính, không thêm thành phần hồ sơ, không tăng yêu cầu, điều kiện nhưng được kéo dài thời gian giải quyết thủ tục đang áp dụng khi cần thiết"],c:2},{id:"vb05-30",s:"",gt:"Giao liên tục, thường xuyên là phân cấp, phải được quy định trong văn bản quy phạm pháp luật của cơ quan, người phân cấp; Bộ trưởng được phân cấp cho UBND, Chủ tịch UBND.",mn:'Nhớ "thường xuyên là phân cấp, phân cấp cần văn bản quy phạm”.',t:"m",q:"Trường hợp Bộ trưởng Bộ X muốn giao Ủy ban nhân dân tỉnh Y thực hiện liên tục, thường xuyên một nhiệm vụ thuộc thẩm quyền của mình. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), việc giao này thuộc hình thức nào và phải được thể hiện bằng văn bản nào?",o:["Ủy quyền, thể hiện trong văn bản của cơ quan, tổ chức, người có thẩm quyền ủy quyền","Phân cấp, thể hiện trong văn bản quy phạm pháp luật của cơ quan, người có thẩm quyền phân cấp","Phân quyền, thể hiện trong luật, nghị quyết do Quốc hội ban hành cho Ủy ban nhân dân tỉnh Y","Phân cấp, thể hiện trong văn bản hành chính cá biệt của Bộ trưởng và Ủy ban nhân dân tỉnh Y"],c:1},{id:"vb05-31",s:"",cc:"Khoán I và khoản 2 Điều 9 Luật Tổ chức Chính phủ năm 2025,",gt:"Giao thực hiện trong khoảng thời gian xác định, thể hiện bằng văn bản của người giao là ủy quyền; phân cấp là giao liên tục, thường xuyên.",mn:'Nhớ "có thời hạn 06 tháng = ủy quyền”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ giao Chủ tịch Ủy ban nhân dân tỉnh Y thực hiện một nhiệm vụ của mình trong thời hạn 06 tháng và thể hiện bằng văn bản. Việc giao này được xác định là hình thức nào?",o:["Phân cấp","Ủy quyền","Phân quyền","Phân công công tác"],c:1},{id:"vb05-32",s:"",cc:"Khoản 5 Điều 5 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ quản trị quốc gia theo hướng hiện đại, hiệu lực, hiệu quả, phục vụ Nhân dân và chịu sự kiểm tra, giám sát của Nhân dân.",mn:'Nhớ "phục vụ Nhân dân - chịu giám sát của Nhân dân”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi quy định về quản trị quốc gia và nền hành chính trong nguyên tắc tổ chức, hoạt động của Chính phủ, yêu cầu nào dưới đây được nêu đúng? Luật FCCP 2025 lrang 1ì",o:["Quản trị quốc gia theo hướng hiện đại, hiệu lực, hiệu quả; phục vụ Nhân dân, chịu sự kiểm tra, giám sát của Quốc hội","Quản trị quốc gia theo hướng truyền thống, ổn định, hiệu quả; phục vụ Nhân dân, chịu sự kiểm tra, giám sát của Nhân dân","Quản trị quốc gia theo hướng hiện đại, hiệu lực, hiệu quả; phục vụ doanh nghiệp, chịu sự kiểm tra, giám sát của Nhân dân","Quản trị quốc gia theo hướng hiện đại, hiệu lực, hiệu quả; phục vụ Nhân dân, chịu sự kiểm tra, giám sát của Nhân dân"],c:3},{id:"vb05-33",s:"",cc:"khoản 3 Điều ” Luật TỔ chức Chính phủ năm 2025.",gt:"Cơ quan trung ương có trách nhiệm hướng dẫn, phối hợp, hợp tác với chính quyền địa phương trong nhiệm vụ được phân quyền; không làm thay.",mn:"Nhớ “hướng dẫn - phối hợp - hợp tác”.",t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), cơ quan nhà nước ở trung ương có trách nhiệm [........ ] với chính quyền địa phương trong các nhiệm vụ, quyền hạn đã được phân quyền cho chính quyền địa phương.",o:["hướng dẫn, phối hợp, hợp tác","hướng dẫn, kiểm tra, xử lý","chỉ đạo, điều hành, giám sát","hướng dẫn, thanh tra, kiểm soát"],c:0},{id:"vb05-34",s:"",cc:"khoản 8 Điều 6 Luật Tổ chức Chính phủ năm 2025,",gt:"Các văn bản khác phải phù hợp với Luật Tổ chức Chính phủ và bảo đảm quyền lực nhà nước được kiểm soát hiệu quả; luật chuyên ngành không được quy định khác Luật này. Luật FCCP 2025 lrang j4",mn:'Nhớ "phù hợp Luật này + kiểm soát quyền lực”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi các văn bản quy phạm pháp luật khác quy định chức năng, nhiệm vụ, quyền hạn, trách nhiệm của Chính phủ, Thủ tướng Chính phủ và Bộ, cơ quan ngang Bộ, các văn bản đó phải bảo đảm yêu cầu nào?",o:["Phù hợp với Luật này, bảo đảm kiểm soát quyền lực nhà nước hiệu quả","Phù hợp với Hiến pháp, bảo đảm quyền lực tập trung thống nhất","Ưu tiên luật chuyên ngành khi có khác biệt","Phù hợp với quy định của Hiến pháp và nghị quyết của Chính phủ, bảo đảm quyền lực nhà nước được kiểm soát hiệu quả ở các cấp"],c:0},{id:"vb05-35",s:"",cc:"Khoản 2 Điều 6 Luật Tổ chức Chính phù năm 2025.",gt:"Chính phủ phối hợp với Tòa án nhân dân, Viện kiểm sát nhân dân theo Luật này, luật về tổ chức Tòa án, Viện kiểm sát và luật khác; không chỉ đạo hoạt động xét xử, kiểm sát.",mn:'Nhớ "Chính phủ phối hợp, không chỉ đạo Tòa án, Viện kiểm sát”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), trong quan hệ giữa Chính phủ với Tòa án nhân dân và Viện kiểm sát nhân dân theo nguyên tắc phân định thẩm quyền, Chính phủ có trách nhiệm thực hiện nội dung nào dưới đây?",o:["Hướng dẫn Tòa án nhân dân, Viện kiểm sát nhân dân về chuyên môn","Phối hợp với Tòa án nhân dân, Viện kiểm sát nhân dân","Chỉ đạo hoạt động của Tòa án nhân dân, Viện kiểm sát nhân dân","Phối hợp với Tòa án nhân dân, Viện kiểm sát nhân dân, Kiểm toán nhà nước và các cơ quan khác trong việc thực hiện nhiệm vụ thuộc thẩm quyền xét xử, kiểm sát"],c:1},{id:"vb05-36",s:"",cc:"Khoản 1 Điều 7, khoản 1 Điều 8 và khoản 1 Điều 9 Luật Tổ chức Chính phủ năm 2025.",gt:"Phân quyền do Quốc hội quy định; phân cấp giao liên tục, thường xuyên; ủy quyền giao trong khoảng thời gian xác định.",mn:'Nhớ "quyền do Quốc hội, cấp thường xuyên, ủy có hạn”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), phân quyền, phân cấp và ủy quyền là ba cơ chế phân định thẩm quyền khác nhau; nhận định nào dưới đây so sánh đúng ba cơ chế này?",o:["Phân quyền do Chính phủ quy định trong nghị định; phân cấp giao thực hiện liên tục, thường xuyên; ủy quyền giao thực hiện trong khoảng thời gian xác định","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp giao thực hiện liên tục, thường xuyên; ủy quyền giao thực hiện trong khoảng thời gian xác định","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp giao thực hiện trong khoảng thời gian xác định; ủy quyền giao thực hiện liên tục, thường xuyên","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp và ủy quyền đều giao thực hiện liên tục, thường xuyên bằng văn bản quy phạm pháp luật"],c:1},{id:"vb05-37",s:"",cc:"Khoản 5 Điều 8 và khoản 6 Điều 9 Luật TỔ chức Chính phủ năm 2025.",gt:'Bên được phân cấp không được phân cấp tiếp, bên được ủy quyền không được ủy quyền tiếp; các phương án còn lại đúng với quy định. ® Mico nhớ: Nhớ "nhận phân cấp, nhận ủy quyền đều không chuyên tiếp”. Luật TCCP 2025 Trong 1b Phạm vi: nhiệm vụ, quyền hạn của Chính phù (Điều 10): trình Quốc hội. UBTVOQH, Chủ tịch nước: tổ chức thi hành Hiến pháp, pháp luật: thống nhất quản lý nền hành chính quốc gia; quản lý kinh tế - xã hội, quốc phòng, an ninh, đối ngoại: trách nhiệm của Chính phủ (Điều 11); quan hệ với Mặt trận Tổ quốc Việt Nam (Điều 12). Đáp án đối chiếu Luật số 63/2025/QH15.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong các nhận định dưới đây về việc phân cấp, ủy quyền trong hệ thống cơ quan nhà nước, nhận định nào SAI so với quy định của Luật?",o:["Việc phân cấp phải được quy định trong văn bản quy phạm pháp luật của cơ quan, người có thẩm quyền phân cấp Luáạt TCCP 2025 Trung 15","Việc ủy quyền phải được thể hiện trong văn bản và quy định cụ thể nội dung, phạm vi, thời hạn ủy quyền","Cơ quan, tổ chức, đơn vị, cá nhân được phân cấp chịu trách nhiệm hoàn toàn về kết quả thực hiện nhiệm vụ được phân cấp","Cơ quan, đơn vị, cá nhân được phân cấp hoặc được ủy quyền được phân cấp tiếp, ủy quyền tiếp nhiệm vụ cho cấp dưới nếu cần thiết"],c:3},{id:"vb05-38",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm b khoản 1 Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:'Chính phủ trình Quốc hội dự toán ngân sách nhà nước và phân bổ ngân sách trung ương, phê chuẩn quyết toán ngân sách nhà nước, trưng cầu ý dân; pháp lệnh thuộc Ủy ban Thường vụ Quốc hội. ® Mico nhớ: Nhớ "dự toán - quyết toán - trưng cầu ý dân”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong nhóm nhiệm vụ, quyền hạn trình Quốc hội quyết định, Chính phủ thực hiện việc nào dưới đây liên quan đến chính sách tài chính, ngân sách và ý kiến của Nhân dân?",o:["Trình thông qua dự toán ngân sách nhà nước và phân bổ ngân sách trung ương: phê chuẩn quyết toán ngân sách nhà nước; sửa đổi Hiến pháp","Trình thông qua dự toán ngân sách nhà nước và phân bổ ngân sách trung ương; phê chuẩn quyết toán ngân sách nhà nước; trưng cầu ý dân","Trình thông qua dự toán ngân sách nhà nước và phân bổ ngân sách địa phương; phê chuẩn quyết toán ngân sách trung ương; trưng cầu ý dân","Trình thông qua dự án pháp lệnh về ngân sách; phân bổ ngân sách trung ương; phê chuẩn quyết toán ngân sách nhà nước; trưng cầu ý dân"],c:1},{id:"vb05-39",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm c khoản 1 Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ trình Quốc hội nghị quyết về thành lập, giải thể, nhập, chia, điều chỉnh địa giới đơn vị hành chính cấp tỉnh và đơn vị hành chính - kinh tế đặc biệt; đơn vị hành chính dưới cấp tỉnh trình Ủy ban Thường vụ Quốc hội. Luật TCCP 2025 Trong 1”",mn:'Nhớ "cấp tỉnh trình Quốc hội, dưới tỉnh trình Thường vụ”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp Chính phủ đề xuất nhập hai đơn vị hành chính liền kề, nghị quyết về thành lập, giải thể, nhập, chia, điều chỉnh địa giới đối với đơn vị hành chính thuộc cấp nào do Chính phủ trình Quốc hội thông qua, bên cạnh đơn vị hành chính - kinh tế đặc biệt?",o:["Cấp xã","Cấp tỉnh","Đặc khu","Thôn, tổ dân phố"],c:1},{id:"vb05-40",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm b khoản 2 Điều 10 Luật Tổ chức € hình phủ năm 2025,",gt:"Việc thành lập, giải thể, nhập, chia, điều chỉnh địa giới đơn vị hành chính dưới cấp tỉnh do Chính phủ trình Ủy ban Thường vụ Quốc hội.",mn:'Nhớ "dưới tỉnh thì Thường vụ Quốc hội".',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp Chính phủ đề xuất điều chỉnh địa giới một số đơn vị hành chính, Chính phủ trình Ủy ban Thường vụ Quốc hội thông qua dự thảo nghị quyết đối với nhóm đơn vị hành chính nào?",o:["Đơn vị hành chính dưới cấp tỉnh","Đơn vị hành chính cấp tỉnh","Đơn vị hành chính - kinh tế đặc biệt","Đơn vị hành chính cấp tỉnh trở lên"],c:0},{id:"vb05-41",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Ñhoên 3 /iệều ID Luật Tổ chức © hình phụ nóm 2025 Chược sưu đổi, bà sung bởi Í uạt số 137. 2025 02415 — hợp nhất tại VBEEN số 2>, VHBIEN- VỊ).",gt:"Nội dung được sửa đổi, bổ sung: Chính phủ quyết định đặc xá theo quy định của pháp luật, không phải trình cơ quan khác quyết định.",mn:'Nhớ "đặc xá do Chính phủ quyết định" (nội dung sửa đổi bởi Luật số 137/2025/QH13).',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), được sửa đổi, bổ sung bởi Luật số 137/2025/QH15 (hợp nhất tại VBHN số 27/VBHN-VPQH), nhiệm vụ, quyền hạn nào dưới đây liên quan đến đặc xá thuộc Chính phủ theo phần nội dung đã được sửa đổi, bổ sung?",o:["Trình Quốc hội quyết định đặc xá","Trình Chủ tịch nước quyết định đặc xá","Quyết định đặc xá","Trình Ủy ban Thường vụ Quốc hội quyết định đặc xá"],c:2},{id:"vb05-42",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"tiềm a khoản 4 Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ báo đảm tính hợp hiến, hợp pháp, kiểm tra việc thi hành các văn bản và xử lý văn bản trái Hiến pháp và pháp luật.",mn:'Nhớ "kiểm tra rồi xử lý văn bản trái luật”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong tổ chức thi hành Hiến pháp, luật, nghị quyết, Chính phủ phát hiện văn bản quy phạm pháp luật của một cơ quan ở địa phương trái Hiến pháp và pháp luật. Chính phủ có nhiệm vụ nào đối với văn bản đó?",o:["Kiểm tra việc thi hành và xử lý văn bản trái Hiến pháp và pháp luật","Báo cáo Quốc hội để Quốc hội trực tiếp xử lý văn bản","Đề nghị Tòa án nhân dân tối cao xử lý văn bản","Kiểm tra việc thi hành văn bản đó nhưng chỉ xử lý khi có kiến nghị của Hội đồng nhân dân hoặc cử tri nơi ban hành văn bản trái pháp luật"],c:0},{id:"vb05-43",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 5 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chuỗi yêu cầu kết thúc băng minh bạch, kỷ luật, kỷ cương hành chính, hiệu lực, hiệu quả, phục vụ Nhân dân.",mn:'Nhớ "minh bạch rồi đến kỷ luật, kỷ cương hành chính”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thống nhất quản lý nền hành chính quốc gia, bảo đảm tính thống nhất, thông suốt, liên tục, dân chủ, pháp quyền, chuyên nghiệp, hiện đại, khoa học, trong sạch, công khai, minh bạch, [......... I, hiệu lực, hiệu quả, phục vụ Nhân dân.",o:["kỷ luật, kỷ cương công vụ","kỷ cương, trách nhiệm hành chính","trách nhiệm, kỷ luật hành chính","kỷ luật, kỷ cương hành chính"],c:3},{id:"vb05-44",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm a khoản 5 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:'Chính phủ thống nhất quản lý về tổ chức bộ máy, cán bộ, công chức, viên chức và công vụ, cải cách hành chính, cải cách chế độ công vụ, công chức; không tuyển dụng, định lương cho từng cá nhân. ® Miẹo nhớ: Nhớ "quản lý chung, không làm thay từng cơ quan".',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong lĩnh vực tổ chức bộ máy hành chính và cán bộ, công chức, viên chức, Chính phủ thống nhất quản lý nhà nước và thực hiện nhiệm vụ nào dưới đây?",o:["Quản lý về tổ chức bộ máy hành chính nhà nước; tuyển dụng trực tiếp cán bộ, công chức, viên chức cho từng cơ quan, đơn vị; cải cách hành chính","Quản lý về tổ chức bộ máy hành chính nhà nước; cán bộ, công chức, viên chức và công vụ; cải cách hành chính, cải cách chế độ công vụ, công chức","Quản lý về tổ chức bộ máy hành chính nhà nước; quyết định mức lương của từng cán bộ, công chức, viên chức; cải cách chế độ công vụ, công chức","Quản lý về tổ chức bộ máy hành chính nhà nước; cán bộ, công chức, viên chức và công vụ trong cả cơ quan nhà nước và doanh nghiệp tư nhân; cải cách hành chính"],c:1},{id:"vb05-45",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm b khoản 5 Điều 10 Luân Tổ chức Chính phủ năm 2025.",gt:"Chính phủ thống nhất quản lý và tổ chức thực hiện chế độ tiền lương đối với cán bộ, công chức, viên chức từ trung ương đến địa phương.",mn:'Nhớ "lương của cán bộ, công chức, viên chức do Chính phủ quản lý thống nhất”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13): Chính phủ thống nhất quản lý nhà nước và tổ chức thực hiện chế độ tiền lương đối với nhóm đối tượng nào dưới đây?",o:["Cán bộ, công chức, viên chức","Cán bộ, công chức cấp trung ương Luáạt TCCP 2025 Trong 19","Công chức, viên chức cấp tỉnh trở xuống","Cán bộ, công chức, người lao động hợp đồng"],c:0},{id:"vb05-46",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điệp ở khoản 5 Điều 1Ú Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ thống nhất quản lý cơ sở hạ tầng, ứng dụng khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số, trí tuệ nhân tạo vào hoạt động của nền hành chính quốc gia.",mn:'Nhớ "hạ tầng + khoa học công nghệ + chuyển đổi số + trí tuệ nhân tạo”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), về quản lý cơ sở hạ tầng và công nghệ trong nền hành chính quốc gia, Chính phủ thống nhất quản lý nội dung nào dưới đây?",o:["Cơ sở hạ tầng, ứng dụng khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, trí tuệ nhân tạo vào hoạt động sản xuất, kinh doanh của doanh nghiệp","Cơ sở hạ tầng, ứng dụng khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, trí tuệ nhân tạo vào hoạt động của nền hành chính quốc gia","Cơ sở hạ tầng, ứng dụng khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số vào hoạt động của các cơ quan lập pháp, cơ quan tư pháp","Cơ sở hạ tầng, ứng dụng khoa học, công nghệ và chuyển đổi số, an ninh mạng, bảo mật thông tin vào hoạt động của nền hành chính quốc gia"],c:1},{id:"vb05-47",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm e khoản 5 Điều TÔ Luật Tổ chức Chính phủ năm 2025,",gt:"Chính phủ lãnh đạo công tác của Bộ, cơ quan ngang Bộ, cơ quan thuộc Chính phủ, Ủy ban nhân dân các cấp: Tòa án nhân dân tối cao thuộc hệ thống cơ quan tư pháp, Chính phủ chỉ hướng dẫn, kiểm tra về tổ chức bộ máy, cán bộ, tài chính.",mn:'Nhớ "Chính phủ lãnh đạo hành chính, không lãnh đạo tư pháp”. Luật FCCP 2025 rang >0',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ lãnh đạo công tác của các cơ quan trong hệ thống hành chính và hướng dẫn, kiểm tra Hội đồng nhân dân các cấp; cơ quan nào dưới đây KHÔNG thuộc phạm vi Chính phủ lãnh đạo công tác?",o:["Các Bộ, cơ quan ngang Bộ","Cơ quan thuộc Chính phủ","Ủy ban nhân dân các cấp","Tòa án nhân dân tối cao"],c:3},{id:"vb05-48",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 6 Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ thống nhất quản lý kinh tế, văn hóa, xã hội, giáo dục, y tế, khoa học, công nghệ, môi trường, thông tin, truyền thông, đối ngoại và hội nhập quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội; không bao gồm hoạt động xét xử, công tố.",mn:'Nhớ "kinh tế -— xã hội, đối ngoại, quốc phòng, an ninh: Chính phủ quản lý; xét xử, công tố: không”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thống nhất quản lý về nhiều ngành, lĩnh vực; nhóm lĩnh vực nào dưới đây được nêu đầy đủ và đúng với phạm vi thống nhất quản lý của Chính phủ?",o:["Kinh tế, văn hóa, xã hội, giáo dục, y tế, khoa học, công nghệ, môi trường, thông tin, truyền thông, đối ngoại và hội nhập quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội, hoạt động xét xử và công tố","Kinh tế, văn hóa, xã hội, giáo dục, y tế, khoa học, công nghệ, môi trường, thông tin, truyền thông, đối ngoại và hội nhập quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội","Kinh tế, văn hóa, xã hội, giáo dục, y tế, khoa học, công nghệ, môi trường, thông tin, truyền thông, ngoại giao và hội nhập kinh tế quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội","Kinh tế, văn hóa, xã hội, giáo dục, v tế, khoa học, công nghệ, môi trường, bưu chính, viễn thông, đối ngoại và hội nhập quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội"],c:1},{id:"vb05-49",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"khoản 7 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính sách phát triển ngành, lĩnh vực, vùng, địa phương phải phù hợp với chủ trương của Đảng, chiến lược, kế hoạch và các mục tiêu, chỉ tiêu, chính sách cơ bản đã được Quốc hội thông qua.",mn:'Nhớ "chính sách của Chính phủ phải khớp với mục tiêu Quốc hội đã thông qua”. Luáạt TCCP 2025 Trong 2]',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ quyết định các chính sách phát triển ngành, lĩnh vực, vùng, địa phương, trừ chính sách thuộc thẩm quyền của Quốc hội và chính quyền địa phương, bảo đảm phù hợp với chủ trương của Đảng, chiến lược và kế hoạch phát triển kinh tế - xã hội của đất nước và các mục tiêu, chỉ tiêu, chính sách, nhiệm vụ cơ bản [......... ÌL",o:["đã được Ủy ban Thường vụ Quốc hội thông qua","đã được Chủ tịch nước công bố","đã được Chính phủ ban hành","đã được Quốc hội thông qua"],c:3},{id:"vb05-50",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm a khoản 8 Điều 1Ù Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ tổ chức thi hành lệnh tổng động viên hoặc động viên cục bộ, lệnh ban bố tình trạng khẩn cấp; quyền ban hành các lệnh này không thuộc Chính phủ.",mn:'Nhớ "Chính phủ tổ chức thi hành lệnh, không tự ban hành lệnh”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong lĩnh vực quốc phòng, an ninh, Chính phủ thực hiện nhiệm vụ nào dưới đây theo chức năng, nhiệm vụ, thẩm quyền của mình?",o:["Tổ chức thi hành lệnh ban bố tình trạng khẩn cấp","Ban bố tình trạng khẩn cấp trong cả nước","Tuyên bố tình trạng chiến tranh","Quyết định tổng động viên hoặc động viên cục bộ và tổ chức thi hành lệnh ban bố tình trạng khẩn cấp để bảo vệ Tổ quốc"],c:0},{id:"vb05-51",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm c khoản # Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ quyết định kỳ, gia nhập, phê duyệt, chấm dứt hiệu lực điều ước quốc tế nhân danh Chính phủ, trừ điều ước quốc tế trình Quốc hội phê chuẩn theo Hiến pháp.",mn:'Nhớ "nhân danh Chính phủ, trừ loại Quốc hội phê chuẩn”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong hoạt động đối ngoại, Chính phủ quyết định việc ký, gia nhập, phê duyệt hoặc chấm dứt hiệu lực điều ước quốc tế nhân danh chủ thể nào, và phạm vi thẩm quyền đô loại trừ trường hợp nào?",o:["Nhân danh Nhà nước, trừ điều ước quốc tế trình Quốc hội phê chuẩn theo quy định của Hiến pháp","Nhân danh Chính phủ, trừ điều ước quốc tế thuộc thẩm quyền ký kết của các Bộ, cơ quan ngang Bộ","Nhân danh Chính phủ, trừ điều ước quốc tế trình Quốc hội phê chuẩn theo quy định của Hiến pháp","Nhân danh Chủ tịch nước, trừ điều ước quốc tế trình Quốc hội phê chuẩn theo quy định của Hiến pháp"],c:2},{id:"vb05-52",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm đ khoản 8 Điều 1Ù Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ quyết định thành lập, tổ chức lại, giải thể cơ quan thuộc Chính phủ; thành lập, bãi bỏ Bộ, cơ quan ngang Bộ do Chính phủ trình Quốc hội.",mn:'Nhớ "cơ quan thuộc Chính phủ do Chính phủ tự quyết, Bộ thì trình Quốc hội”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong nhóm nhiệm vụ về tổ chức bộ máy, Chính phủ quyết định việc thành lập, tổ chức lại, giải thể loại cơ quan nào dưới đây, còn việc thành lập, bãi bỏ Bộ, cơ quan ngang Bộ thì phải trình Quốc hội?",o:["Cơ quan ngang Bộ","Bộ thuộc Chính phủ","Cơ quan thuộc Chính phủ","Cơ quan chuyên môn thuộc Ủy ban nhân dân Luật 1CCP 2U925 Irong 2>?"],c:2},{id:"vb05-53",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điển e khoản 8 Điều 10 Luật TỔ chức Chính phủ năm 2025,",gt:"Chính phủ quy định khung số lượng, tổ chức, tiêu chí thành lập, số lượng cấp phó tối đa của cơ quan chuyên môn; không bố nhiệm người đứng đầu từng cơ quan.",mn:'Nhớ "Chính phủ quy định khung, không bố nhiệm từng người”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ quy định về cơ quan chuyên môn thuộc Ủy ban nhân dân; nội dung nào dưới đây KHÔNG thuộc thẩm quyền quy định của Chính phủ?",o:["Quyết định bổ nhiệm người đứng đầu từng cơ quan chuyên môn thuộc Ủy ban nhân dân","Khung số lượng cơ quan chuyên môn thuộc Ủy ban nhân dân","Tổ chức các cơ quan chuyên môn thuộc Ủy ban nhân dân","Tiêu chí thành lập, số lượng cấp phó tối đa của người đứng đầu cơ quan chuyên môn"],c:0},{id:"vb05-54",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",gt:"Chính phủ là đại diện chủ sở hữu đổi với tài sản công thuộc sở hữu toàn dân và thực hiện chức năng chủ sở hữu phần vốn của Nhà nước tại doanh nghiệp có vốn nhà nước.",mn:'Nhớ "tài sản công: đại diện chủ sở hữu; vốn nhà nước: chủ sở hữu”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), đối với tài sản công và phần vốn của Nhà nước tại doanh nghiệp, Chính phủ thực hiện chức năng nào dưới đây, xét theo từng loại tài sản, vốn?",o:["Chủ sở hữu tài sản công; đại diện chủ sở hữu phần vốn nhà nước","Quản lý tài sản công; trực tiếp điều hành doanh nghiệp có vốn nhà nước","Đại diện chủ sở hữu tài sản công; chủ sở hữu phần vốn nhà nước tại doanh nghiệp","Đại diện chủ sở hữu tài sản công thuộc sở hữu toàn dân; chủ sở hữu phần vốn của Nhà nước tại doanh nghiệp có vốn nhà nước, đồng thời quyết định giá bán tài sản"],c:2},{id:"vb05-55",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản Ì Điều LÍ Luật Tổ chức Chính phủ năm 2025,",gt:"Chính phủ chịu trách nhiệm trước Quốc hội về nhiệm vụ, quyền hạn, kết quả quản lý, điều hành và chủ trương, chính sách do mình đề xuất.",mn:'Nhớ "Chính phủ chịu trách nhiệm trước Quốc hội”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trách nhiệm của Chính phủ về việc thực hiện nhiệm vụ, quyền hạn của mình, về kết quả quản lý, điều hành bộ máy hành chính nhà nước được xác lập trước cơ quan nào? Luật FCCP 2025 rung —3",o:["Chủ tịch nước","Ủy ban Thường vụ Quốc hội","Mặt trận Tổ quốc Việt Nam","Quốc hội"],c:3},{id:"vb05-56",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 2 Điều 11 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ báo cáo công tác một năm hai lần, ngoài ra báo cáo đột xuất theo yêu cầu.",mn:"Nhớ “một năm hai lần” như báo cáo giữa năm và cuối năm.",t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ báo cáo công tác của Chính phủ với Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước một năm |........ các cơ quan này. ] và báo cáo công tác đột xuất theo yêu cầu của",o:["một lần","ba lần","bốn lần","hai lần"],c:3},{id:"vb05-57",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"khoản 2 Điều LÍ Luật Tổ chức Chính phủ năm 2025.",gt:"Báo cáo đột xuất thực hiện theo yêu cầu của Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước.",mn:'Nhớ "ba nơi nhận báo cáo định kỳ cùng là ba nơi được yêu cầu báo cáo đột xuất”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), ngoài chế độ báo cáo công tác định kỳ một năm hai lần, Chính phủ phải báo cáo công tác đột xuất trong trường hợp nào dưới đây?",o:["Khi Tòa án nhân dân tối cao, Quốc hội yêu cầu","Khi Mặt trận Tổ quốc Việt Nam yêu cầu","Khi Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước yêu cầu","Khi Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước hoặc Ủy ban trung ương Mặt trận Tổ quốc Việt Nam yêu cầu bằng văn bản gửi Chính phủ"],c:2},{id:"vb05-58",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 3 Điều 12 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ gửi dự thảo để Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội có liên quan tham gia ý kiến.",mn:'Nhớ "dự thảo gửi Mặt trận và tổ chức chính trị - xã hội”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp Bộ Z chủ trì soạn thảo một dự thảo nghị định trình Chính phủ, khi xây Luật FCCP 2025 lrang —4 dựng dự án luật, dự án pháp lệnh, dự thảo nghị định, dự thảo nghị quyết, Chính phủ gửi dự thảo văn bản để chủ thể nào tham gia ý kiến?",o:["Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của các hội nghề nghiệp có liên quan","Hội đồng Dân tộc của Quốc hội và cơ quan trung ương của tổ chức chính trị - xã hội có liên quan","Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và Hội đồng nhân dân các cấp có liên quan","Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội có liên quan"],c:3},{id:"vb05-59",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 2 Điều 12 Luật Tổ chức Chính phủ năm 2025.",gt:'Hai bên xây dựng quy chế phối hợp công tác. ® Miẹo nhớ: Nhớ "phối hợp thì có quy chế phối hợp công tác”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ và Ủy ban trung ương Mặt trận Tổ quốc Việt Nam, cơ quan trung ương của tổ chức chính trị - xã hội xây dựng [ ] để phối hợp thực hiện nhiệm vụ và quyền hạn của mỗi bên.",o:["chương trình hành động chung","kế hoạch công tác hãẳng năm","quy chế phối hợp công tác","nghị quyết liên tịch"],c:2},{id:"vb05-60",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoán ö Điều 12 Luật TỔ chức Chính phủ năm 2025. Luáạt TCCP 2025 Trung 25",gt:"Chính phủ nghiên cứu, giải quyết và trả lời các kiến nghị của Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội.",mn:'Nhớ "nghiên cứu - giải quyết - trả lời”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), đối với các kiến nghị của Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội gửi đến Chính phủ, Chính phủ có trách nhiệm nào dưới đây?",o:["Chuyến kiến nghị đến Quốc hội xem xét","Thông báo kết quả cho Quốc hội","Nghiên cứu kiến nghị, giao Bộ trưởng Bộ Nội vụ trả lời bằng văn bản và báo cáo Thủ tướng Chính phủ về kết quả giải quyết","Nghiên cứu, giải quyết và trả lời kiến nghị"],c:3},{id:"vb05-61",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản Ì Điều 4 và Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Thủ tướng Chính phủ do Quốc hội bầu; Chính phủ không tự bầu, miễn nhiệm, bãi nhiệm thành viên của mình. Các nội dung còn lại thuộc nhiệm vụ, quyền hạn của Chính phủ.",mn:'Nhớ "Quốc hội bầu Thủ tướng, Chính phủ không tự bầu mình”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nội dung nào dưới đây KHÔNG thuộc nhiệm vụ, quyền hạn của Chính phủ?",o:["Thống nhất quản lý nền hành chính quốc gia","Bầu, miễn nhiệm, bãi nhiệm Thủ tướng Chính phủ và các thành viên khác của Chính phủ","Tổ chức thi hành Hiến pháp, luật, nghị quyết của Quốc hội","Trình Quốc hội dự toán ngân sách nhà nước"],c:1},{id:"vb05-62",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm g và điểm h khoản 5 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ thống nhất quản lý nhà nước về tổ chức và hoạt động của các hội, tổ chức phi chính phủ và về thi đua, khen thưởng.",mn:'Nhớ "hội và tổ chức phi chính phủ đi cùng thi đua, khen thưởng".',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thống nhất quản lý nhà nước về tổ chức và hoạt động của [......... thời thống nhất quản lý nhà nước về công tác thi đua, khen thưởng.",o:["các hội, tổ chức chính trị - xã hội","các tổ chức tôn giáo, tín ngưỡng","các hội, tổ chức phi chính phủ","các doanh nghiệp nhà nước"],c:2},{id:"vb05-63",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm ¡ khoản 5 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:'Chính phủ hướng dẫn, kiểm tra trong cơ quan lập pháp, cơ quan tư pháp, cơ quan công tổ - kiểm sát hoạt động tư pháp và Kiểm toán nhà nước. ® Miẹo nhớ: Nhớ "lập pháp - tư pháp - công tố, kiểm sát - Kiểm toán nhà nước”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ hướng dẫn, kiểm tra về tổ chức bộ máy, cán bộ, công chức, viên chức, cải cách hành chính, thi đua, khen thưởng và tài chính, tài sản công trong những cơ quan nào dưới đây?",o:["Cơ quan thực hiện quyền lập pháp, cơ quan thực hiện quyền tư pháp, cơ quan thực hành quyền công tố, kiểm sát hoạt động tư pháp, Ủy ban trung ương Mặt trận Tổ quốc Việt Nam","Cơ quan thực hiện quyền lập pháp, cơ quan thực hiện quyền tư pháp, cơ quan thực hành quyền công tố, kiểm sát hoạt động tư pháp, Kiểm toán nhà nước Luật TCCP 2025 Trung >5","Cơ quan thực hiện quyền lập pháp, cơ quan thực hiện quyền hành pháp, cơ quan thực hành quyền công tố, kiểm sát hoạt động tư pháp, Kiểm toán nhà nước","Cơ quan thực hiện quyền lập pháp, cơ quan thực hiện quyền tư pháp, các tổ chức chính trị - xã hội, các hội, tổ chức phi chính phủ, Kiểm toán nhà nước"],c:1},{id:"vb05-64",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm h khoản 8 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ được sự đồng ý của cấp có thẩm quyền, báo cáo Ủy ban Thường vụ Quốc hội cho phép, sau đó báo cáo Quốc hội tại kỳ họp gần nhất.",mn:'Nhớ "đồng ý — cho phép - báo cáo kỳ họp gần nhất”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), để huy động nguồn lực triển khai một chương trình mục tiêu quốc gia, Chính phủ căn áp dụng giải pháp khác với quy định của luật. Trong trường hợp này, Chính phủ phải thực hiện trình tự nào dưới đây?",o:["Tự quyết định thực hiện, sau đó báo cáo Quốc hội","Được cấp có thẩm quyền đồng ý, báo cáo Ủy ban Thường vụ Quốc hội cho phép, sau đó báo cáo Quốc hội tại kỳ họp gần nhất","Trình Quốc hội thông qua trước khi thực hiện","Báo cáo Chủ tịch nước cho phép thực hiện giải pháp khác, sau đó báo cáo Ủy ban Thường vụ Quốc hội và Quốc hội tại kỳ họp gần nhất sau khi kết thúc chương trình"],c:1},{id:"vb05-65",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 6 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ quyết định biện pháp bảo vệ độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ, góp phần bảo vệ hòa bình ở khu vực và trên thế giới.",mn:'Nhớ "hòa bình ở khu vực và trên thế giới”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13): Chính phủ quyết định biện pháp cụ thể để bảo vệ độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Tổ quốc, đồng thời góp phần bảo vệ hòa bình ở phạm vi nào?",o:["Khu vực và trên thế giới","Khu vực Đông Nam Á","Các nước láng giềng","Các quốc gia thành viên Liên hợp quốc"],c:0},{id:"vb05-66",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm d khoản 8 Điều 1Ù Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ tổ chức, chỉ đạo cơ quan đại diện ở nước ngoài và tại các tổ chức quốc tế, bảo vệ lợi ích của tổ chức, công dân Việt Nam ở nước ngoài và người Việt Nam định cư ở nước ngoài; tổ chức, cá nhân nước ngoài tại Việt Nam thuộc đối tượng quản lý.",mn:'Nhớ "cơ quan đại diện ở nước ngoài, bảo vệ cũng dân ở nước ngoài”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong công tác đối ngoại, Chính phủ tổ chức và chỉ đạo hoạt động của cơ quan đại Luáạt TCCP 2025 Trung 27 diện của Nhà nước ở đâu, đồng thời bảo vệ lợi ích chính đáng của những đối tượng nào?",o:["Ở nước ngoài và tại các tổ chức quốc tế; bảo vệ lợi ích của tổ chức, công dân Việt Nam ở nước ngoài và tổ chức, cá nhân nước ngoài tại Việt Nam","Ở nước ngoài và tại các tổ chức quốc tế; bảo vệ lợi ích của tổ chức, công dân Việt Nam ở nước ngoài và người Việt Nam định cư ở nước ngoài","Tại các tỉnh biên giới và tại các tổ chức quốc tế; bảo vệ lợi ích của tổ chức, công dân Việt Nam ở nước ngoài và người Việt Nam định cư ở nước ngoài","Ở nước ngoài và tại các tổ chức quốc tế; bảo vệ lợi ích của công dân Việt Nam trong nước và người Việt Nam định cư ở nước ngoài"],c:1},{id:"vb05-67",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 5 Điều 12 Luật Tổ chưức Chính phủ năm 2025.",gt:"Chính phủ tạo điều kiện để Mặt trận và tổ chức chính trị - xã hội thực hiện phản biện xã hội, giám sát hoạt động của cơ quan nhà nước, đại biểu dân cử, cán bộ, cung chức, viên chức.",mn:"Nhớ “phản biện xã hội và giám sát”.",t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ tạo điều kiện thuận lợi để Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội tuyên truyền, phổ biến pháp luật, bảo đảm quyền làm chủ của Nhân dân, [........ | hoạt động của cơ quan nhà nước, đại biểu dân cử, cán bộ, công chức và viên chức.",o:["phản biện xã hội, thanh tra","tham vấn xã hội, giám sát","phản biện xã hội, giám sát","phản biện chính sách, kiểm tra"],c:2},{id:"vb05-68",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điều 10 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ thực hiện nhiệm vụ, quyền hạn theo Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội và các nhiệm vụ cụ thể của Luật; không chỉ theo phân công của Thủ tướng.",mn:'Nhớ "căn cứ của Chính phủ là Hiến pháp, luật, nghị quyết, pháp lệnh”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thực hiện nhiệm vụ, quyền hạn theo các căn cứ pháp lý và nhiệm vụ cụ thể do Luật quy định; nhận định nào dưới đây về căn cứ thực hiện nhiệm vụ, quyền hạn của Chính phủ là SAI?",o:["Thực hiện theo Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội","Thực hiện các nhiệm vụ, quyền hạn cụ thể do Luật này quy định ngoài các căn cứ theo Hiến pháp và luật Luật FCCP 2025 lrung —ö","Chịu trách nhiệm về quyết định của mình khi quy định các chính sách theo chức năng, nhiệm vụ, thẩm quyền","Chính phủ chỉ thực hiện nhiệm vụ, quyền hạn do Thủ tướng Chính phủ giao cho từng thành viên Chính phủ"],c:3},{id:"vb05-69",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Điểm d khoản 5 Điều 10 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ thống nhất tổ chức công tác thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo, phòng, chống quan liêu, tham nhũng, tiêu cực, lãng phí; điều tra, truy tỐ, xét xử thuộc cơ quan khác.",mn:'Nhớ "thanh tra - kiểm tra - khiếu nại, tố cáo - chống quan liêu, tham nhũng, tiêu cực, lãng phí".',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thống nhất tổ chức công tác nào dưới đây trong hoạt động của bộ máy hành chính nhà nước và các hoạt động kinh tế - xã hội?",o:["Thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo, điều tra, truy tố các hành vi tham nhũng, tiêu cực, lãng phí","Thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo, phòng, chống quan liêu, tham nhũng, tiêu cực, lãng phí","Thanh tra, kiểm tra, xét xử khiếu nại, tố cáo, phòng, chống quan liêu, tham nhũng, tiêu cực, lãng phí","Thanh tra, kiểm tra, giải quyết khiếu nại, tố cáo, phòng, chống tham nhũng, buôn lâu, gian lận thương mại"],c:1},{id:"vb05-70",s:"CHƯƠNG II - MỤC 1: NHIỆM VỤ, QUYỀN HẠN VÀ TRÁCH NHIỆM CỦA CHÍNH PHỦ",cc:"Khoản 4 Điều 12 Luật Tổ chức Chính phủ năm 2025. Luật TCCP 2025 Trung >9",gt:"Chính phủ thông báo các quyết định, chủ trương quan trọng liên quan đến nhiều tầng lớp nhân dân.",mn:'Nhớ "việc gì liên quan nhiều tầng lớp nhân dân thì thông báo cho Mặt trận". Luật FCCP 2025 lrang.số Phạm vi: nhiệm vụ, quyền hạn của Thủ tướng Chính phủ (Điều 13): trình Quốc hội, LUBTVQH, Chủ tịch nước; lãnh đạo công tác của Chính phủ; lãnh đạo hệ thống hành chính; ban hành quyết định, chỉ thị; bổ nhiệm, phê chuẩn, giao quyền; trách nhiệm của Thủ tướng (Điều 14); Phó Thủ tướng (Điều 15). Đáp án đối chiếu Luật số',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Chính phủ thường xuyên thông báo cho Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội về tình hình kinh tế - xã hội và các quyết định, chủ trương quan trọng của Chính phủ liên quan đến |[........ l.",o:["toàn bộ doanh nghiệp trong nước","quyền lợi của cán bộ, công chức","quan hệ đối ngoại của Nhà nước","nhiều tầng lớp nhân dân"],c:3},{id:"vb05-71",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:'Thủ tướng trình Quốc hội phê chuẩn đề nghị bổ nhiệm, miễn nhiệm, cách chức Phó Thủ tướng, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ; Thứ trưởng do Thủ tướng bổ nhiệm. ® Mico nhớ: Nhớ "Quốc hội phê chuẩn Phó Thủ tướng và Bộ trưởng”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp cần bố nhiệm Bộ trưởng mới cho một Bộ, Thủ tướng Chính phủ trình Quốc hội phê chuẩn đề nghị bổ nhiệm, miễn nhiệm, cách chức đối với nhóm chức danh nào dưới đây của thành viên Chính phủ?",o:["Bộ trưởng, Thủ trưởng cơ quan ngang Bộ, Thứ trưởng","Phó Thủ tướng, Bộ trưởng, Chủ tịch Ủy ban nhân dân cấp tỉnh","Phó Thủ tướng Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ, đại sứ đặc mệnh toàn quyền và Thủ trưởng, chức vụ tương đương thuộc Bộ","Phó Thủ tướng, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ"],c:3},{id:"vb05-72",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Trong thời gian Quốc hội không họp, Thủ tướng trình Chủ tịch nước quyết định tạm đình chỉ công tác của Phó Thủ tướng, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ.",mn:'Nhớ "Quốc hội nghị thì Chủ tịch nước quyết định tạm đình chỉ".',t:"m",q:"Trường hợp trong thời gian Quốc hội không họp, một Bộ trưởng bị xem xét tạm đình chỉ công tác. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ trình chủ thể nào quyết định việc tạm đình chỉ công tác đó?",o:["Ủy ban Thường vụ Quốc hội","Chủ tịch Quốc hội","Chủ tịch nước","Phó Thủ tướng thường trực"],c:2},{id:"vb05-73",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 2 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng trình Ủy ban Thường vụ Quốc hội phê chuẩn đề nghị bổ nhiệm. miễn nhiệm đại sứ đặc mệnh toàn quyền.",mn:'Nhớ “đại sứ do Ủy ban Thường vụ Quốc hội phê chuẩn".',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp cần bố nhiệm đại sứ đặc mệnh toàn quyền của nước Cộng hòa xã hội Luật TCCP 2025 Trong 31 chủ nghĩa Việt Nam tại một nước, Thủ tướng Chính phủ trình cơ quan nào phê chuẩn đề nghị bổ nhiệm, miễn nhiệm?",o:["Quốc hội","Ủy ban Thường vụ Quốc hội","Chủ tịch nước","Chính phủ"],c:1},{id:"vb05-74",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 3 và điểm b khoản Ð Điều 13 Luật Tổ chức C© hình phụ năm 2025.",gt:"Thủ tướng trình Chủ tịch nước các nội dung về quân hàm cấp tướng. Tổng Tham mưu trưởng, Chủ nhiệm Tổng cục Chính trị. khen thưởng, quốc tịch; con Thứ trưởng do Thủ tướng bổ nhiệm, miễn nhiệm, cách chức.",mn:'Nhớ "Thứ trưởng do Thủ tướng quyết, không trình Chủ tịch nước”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ trình Chủ tịch nước quyết định nhiều nội dung; nội dung nào dưới đây KHÔNG thuộc nhóm nội dung Thủ tướng Chính phủ trình Chủ tịch nước quyết định?",o:["Phong, thăng, giáng, tước quân hàm cấp tướng, chuẩn đô đốc, phó đô đốc, đô đốc hải quân","Bổ nhiệm, miễn nhiệm, cách chức Tổng Tham mưu trưởng, Chủ nhiệm Tổng cục Chính trị Quân đội nhân dân Việt Nam","Tặng thưởng huân chương, huy chương, giải thưởng nhà nước, danh hiệu vinh dự nhà nước; quyết định nhập, thôi, tước quốc tịch","Bổ nhiệm, miễn nhiệm, cách chức Thứ trưởng, chức vụ tương đương thuộc Bộ, cơ quan ngang Bộ"],c:3},{id:"vb05-75",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",gt:"Thủ tướng triệu tập và chủ trì các phiên họp của Chính phủ, quyết định chương trình công tác của Chính phủ, Thủ tướng.",mn:'Nhớ "Thủ tướng triệu tập và chủ trì phiên họp”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ có nhiệm vụ......... ] các phiên họp của Chính phủ, quyết định chương trình công tác của Chính phủ, Thủ tướng Chính phủ.",o:["chủ trì và điều hành","triệu tập và điều hành","triệu tập và chủ trì","tham dự và chủ trì"],c:2},{id:"vb05-76",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm c khoản 4 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:'Thủ tướng chỉ đạo, điều hòa, phối hợp hoạt động giữa các thành viên Chính phủ và quyết định các vấn đề khi còn có ý kiến khác nhau giữa các Bộ trưởng, Thủ trưởng cơ quan ngang Bộ. ® Miẹo nhớ: Nhớ "Bộ trưởng bất đồng ý kiến thì Thủ tướng quyết”.',t:"m",q:"Trường hợp Bộ trưởng Bộ X và Bộ trưởng Bộ Y còn có ý kiến khác nhau về một vấn đề thuộc phạm vi phối hợp liên ngành. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), ai là chủ thể quyết định vấn đề đó?",o:["Phó Thủ tướng thường trực","Chủ tịch nước","Chủ nhiệm Văn phòng Chính phủ","Thủ tướng Chính phủ"],c:3},{id:"vb05-77",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm e khoản 4 Điều 13 Luật TỔ chức Chính phủ năm 2025.",gt:"Thủ tướng quyết định biện pháp cấp bách và báo cáo cơ quan có thẩm quyền của Đảng, Quốc hội trong thời gian gần nhất.",mn:'Nhớ "biện pháp cấp bách thì báo cáo trong thời gian gần nhất”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trường hợp thật cần thiết vì lợi ích quốc gia, phòng, chống thiên tai, dịch bệnh, Thủ tướng Chính phủ quyết định áp dụng các biện pháp cấp bách khác quy định của pháp luật hiện hành, báo cáo cơ quan có thẩm quyền của Đảng, Quốc hội trong thời gian [........ I.",o:["sớm nhất","thích hợp","gần nhất","kịp thời"],c:2},{id:"vb05-78",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm d khoản 5 Điều 13 Luật Tổ chức Chính phủ năm 2025. Luáạt TCCP 2025 Trong 33",gt:"Thủ tướng lãnh đạo, chỉ đạo cải cách hành chính và cải cách chế độ công vụ, công chức trong hệ thống hành chính nhà nước từ trung ương đến địa phương.",mn:'Nhớ "cải cách hành chính đi cùng cải cách công vụ, công chức”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ lãnh đạo, chỉ đạo công tác cải cách nào trong hệ thống hành chính nhà nước từ trung ương đến địa phương?",o:["Công tác cải cách hành chính và cải cách chế độ tiền lương, bảo hiểm xã hội","Công tác cải cách hành chính và cải cách hoạt động xét xử, thi hành án","Công tác cải cách hành chính và cải cách chế độ công vụ, công chức","Công tác cải cách tổ chức bộ máy và cải cách chế độ công vụ, công chức"],c:2},{id:"vb05-79",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm a khoản 6 Điều 13 Luật TỔ chức Chính phủ năm 2025.",gt:"Trong thời gian Quốc hội không họp, Thủ tướng quyết định giao quyền Bộ trưởng, Thủ trưởng cơ quan ngang Bộ khi khuyết; việc bổ nhiệm Bố trướng do Quốc hội phê chuẩn.",mn:'Nhớ "khuyết Bộ trưởng thì Thủ tướng giao quyền”.',t:"m",q:"Trường hợp trong thời gian Quốc hội không họp, một Bộ trưởng bị khuyết độ nghỉ hưu. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ có thẩm quyền nào để bảo đảm hoạt động liên tục của Bộ đó?",o:["Quyết định giao quyền Bộ trưởng trong thời gian Quốc hội không họp, vì Bộ trưởng bị khuyết","Quyết định bổ nhiệm Bộ trưởng mới trong thời gian Quốc hội không họp, vì Bộ trưởng bị khuyết","Đề nghị Chủ tịch nước quyết định giao quyền Bộ trưởng trong thời gian Quốc hội không họp","Quyết định giao quyền Bộ trưởng sau khi có ý kiến của Ủy ban Thường vụ Quốc hội"],c:0},{id:"vb05-80",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm a khoản 6 Điều 13 Luậi Tổ chức Chính phủ năm 2025.",gt:"Trong thời gian giữa hai kỳ họp HĐND cấp tỉnh, Thủ tướng quyết định giao quyền Chủ tịch UBND cấp tỉnh khi khuyết.",mn:"Nhớ “khuyết Chủ tịch UBND tỉnh, giữa hai kỳ họp thì Thủ tướng giao quyền”.",t:"m",q:"Trường hợp giữa hai kỳ họp Hội đồng nhân dân tỉnh Y, Chủ tịch Ủy ban nhân dân tỉnh Y bị khuyết. Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), cơ quan, người nào có thẩm quyền quyết định giao quyền Chủ tịch Ủy ban nhân dân tỉnh Y?",o:["Thủ tướng Chính phủ","Chủ tịch nước","Hội đồng nhân dân tỉnh Y","Bộ trưởng Bộ Nội vụ"],c:0},{id:"vb05-81",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 và điểm b khoản 6 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng bổ nhiệm, miễn nhiệm, cách chức Thứ trưởng, người đứng đầu và cấp phó cơ quan thuộc Chính phủ; Bộ trưởng do Thủ tướng trình Quốc hội phê chuẩn.",mn:'Nhớ "Bộ trưởng do Quốc hội phê chuẩn, Thứ trưởng do Thủ tướng bổ nhiệm”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhân sự nào dưới đây KHÔNG thuộc thẩm quyền bổ nhiệm, miễn nhiệm, cách chức của Thủ tướng Chính phủ? Luật FCCP 2025 lrang.š4",o:["Thứ trưởng, chức vụ tương đương thuộc Bộ, cơ quan ngang Bộ","Người đứng đầu cơ quan thuộc Chính phủ","Bộ trưởng, Thủ trưởng cơ quan ngang Bộ","Cấp phó của người đứng đầu cơ quan thuộc Chính phủ"],c:2},{id:"vb05-82",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm c khoản © Điều 13 Luật TỔ chức Chính phủ năm 2025.",gt:'Với Phó Chủ tịch UBND cấp tỉnh, Thủ tướng yêu cầu Chủ tịch UBND cấp tỉnh thực hiện việc tạm đình chỉ công tác, cách chức theo phân cấp quản lý cán bộ khi không hoàn thành nhiệm vụ hoặc vi phạm pháp luật; riêng Chủ tịch UBND cấp tính thì Thủ tướng trực tiếp tạm đình chỉ. ® Miẹo nhớ: Nhớ "Chủ tịch tỉnh: Thủ tướng trực tiếp; Phó Chủ tịch: yêu cầu Chủ tịch thực hiện”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13): Phó Chủ tịch Ủy ban nhân dân tỉnh Y không hoàn thành nhiệm vụ được cấp có thẩm quyền giao. Thủ tướng Chính phủ có thẩm quyền nào để xử lý trong trường hợp này?",o:["Yêu cầu Hội đồng nhân dân tỉnh Y thực hiện việc tạm đình chỉ công tác, cách chức theo phân cấp quản lý cán bộ","Yêu cầu Chủ tịch Ủy ban nhân dân tỉnh Y thực hiện việc tạm đình chỉ công tác, cách chức theo phân cấp quản lý cán bộ","Trực tiếp quyết định tạm đình chỉ công tác, cách chức theo phân cấp quản lý cán bộ mà không qua Chủ tịch Ủy ban nhân dân tỉnh Y","Yêu cầu Chủ tịch Ủy ban nhân dân tỉnh Y thực hiện việc điều động, luân chuyển công tác theo phân cấp quản lý cán bộ"],c:1},{id:"vb05-83",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm d khoản 6 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:'Khi cần thiết, Thủ tướng quyết định thành lập hội đồng, ủy ban hoặc ban để giúp Thủ tướng nghiên cứu, chỉ đạo, phối hợp giải quyết những vấn đề quan trọng liên ngành. ® Miẹo nhớ: Nhớ "việc liên ngành thì lập hội đồng, ủy ban hoặc ban phối hợp”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ cần giải quyết một vấn đề quan trọng liên ngành liên quan đến nhiều Bộ. Thủ tướng Chính phủ có thể quyết định thành lập tổ chức nào, nhằm mục đích gì?",o:["Bộ mới thay thế các Bộ có liên quan","Cơ quan thuộc Chính phủ đề quản lý ngành lâu dài","Hội đồng, ủy ban hoặc ban giúp phối hợp giải quyết vấn đề liên ngành","Hội đồng, ủy ban hoặc ban thường trực trong cơ cấu của Chính phủ để quản lý nhà nước lâu dài về một ngành, lĩnh vực cụ thể thay cho các Bộ Luật TCCP 2025 Irung 35"],c:2},{id:"vb05-84",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 6 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng Chính phủ ban hành quyết định, chỉ thị; nghị định, nghị quyết là văn bản của Chính phủ với tư cách tập thể, còn thông tư là văn bản của Bộ trưởng.",mn:'Nhớ cụm "Thủ tướng - quyết định, chỉ thị": người đứng đầu điều hành bằng quyết định, chỉ thị, giống như giám đốc ra quyết định và chỉ thị nội bộ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), trong hệ thống cơ quan hành chính nhà nước từ trung ương đến địa phương, Thủ tướng Chính phủ ban hành loại văn bản nào dưới đây và đồng thời hướng dẫn, kiểm tra việc thi hành các văn bản đó?",o:["Pháp lệnh và nghị quyết","Nghị định và nghị quyết","Thông tư và thông tư liên tịch","Quyết định và chỉ thị"],c:3},{id:"vb05-85",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 Điều 14 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng Chính phủ chịu trách nhiệm trước Quốc hội về hoạt động của Chính phủ và hệ thống hành chính nhà nước. Chủ tịch nước chỉ là chủ thể đề nghị Quốc hội bầu Thủ tướng.",mn:'Nhớ cụm "Quốc hội bầu - Quốc hội chịu trách nhiệm”: cơ quan nào bầu ra thì người đó báo cáo và chịu trách nhiệm trước Quốc hội, như nhân viên chịu trách nhiệm với bên đã tuyển dụng mình. Luật TCCP 2025 Trung 3b',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), về hoạt động của Chính phủ và hệ thống hành chính nhà nước từ trung ương đến địa phương, cung như về các quyết định và kết quả thực hiện các quyết định của mình, Thủ tướng Chính phủ phải chịu trách nhiệm trước cơ quan nào?",o:["Chủ tịch nước, vì Chủ tịch nước là người đề nghị Quốc hội bầu Thủ tướng Chính phủ theo quy định của Hiến pháp","Quốc hội","Ủy ban Thường vụ Quốc hội","Hội đồng nhân dân cấp tỉnh"],c:1},{id:"vb05-86",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 2 Điều 14 Luật Tổ chức Chính phủ năm 2025.",gt:"Trong trường hợp cần thiết, Thủ tướng Chính phủ ủy quyền cho Phó Thủ tướng Chính phủ thực hiện việc giải trình, trả lời chất vấn của đại biểu Quốc hội; không chuyên cho chủ thể khác.",mn:'Nhớ cụm "Thủ tướng bận — Phó Thủ tướng thay”: người "số hai” trong Chính phủ là Phó Thủ tướng Chính phủ, giông như phó giám đốc được ủy quyền khi giám đốc di vãng.',t:"m",q:"Trường hợp đại biểu Quốc hội chất vấn về một vấn đề thuộc trách nhiệm điều hành của Chính phủ nhưng Thủ tướng Chính phủ có việc đột xuất không thể trực tiếp trả lời, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ được xử lý theo cách nào khi giải trình, trả lời chất vấn?",o:["Ủy quyền cho Phó Thủ tướng Chính phủ thực hiện","Ủy quyền cho Bộ trưởng Bộ Nội vụ trả lời và báo cáo bằng văn bản với Ủy ban Thường vụ Quốc hội sau mỗi phiên chất vấn","Chuyến câu hỏi cho Chủ tịch nước","Đề nghị hoãn đến kỳ họp sau"],c:0},{id:"vb05-87",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 3 Điều 14 Luật Tổ chưức Chính phủ năm 2025.",gt:"Chế độ báo cáo trước Nhân dân của Thủ tướng Chính phủ được thực hiện thông qua các phương tiện thông tin đại chúng, đối với những vấn đề quan trọng thuộc thẩm quyền của Chính phủ và Thủ tướng.",mn:'Nhớ cụm "Báo cáo Nhân dân - báo chí”: muốn nói với cả nước thì dựng phương tiện thông tin đại chúng, như thông báo lớn phải đăng báo, phát sống.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Thủ tướng Chính phủ thực hiện chế độ báo cáo trước Nhân dân thông qua [........ về những vấn đề quan trọng thuộc thẩm quyền giải quyết của Chính phủ và Thủ tướng Chính phủ.",o:["các phương tiện thông tin đại chúng","các kỳ họp Hội đồng nhân dân","các cuộc họp báo định kỳ hàng quý","văn bản gửi Mặt trận Tổ quốc"],c:0},{id:"vb05-88",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản Ì Điều l5 Luật Tổ chức Chính phủ năm 2025.",gt:"Phó Thủ tướng nhận việc từ Thủ tướng Chính phủ và chịu trách nhiệm trước Thủ tướng về nhiệm vụ được phân công; riêng hoạt động chung của Chính phủ thì cũng chịu trách nhiệm tập thể.",mn:'Nhớ cụm "Ai giao việc — báo cáo người đó”: Phó Thủ tướng nhận việc và chịu trách nhiệm trước Thủ tướng, như phó phòng nhận việc và báo cáo trưởng phòng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Phó Thủ tướng Chính phủ giúp Thủ tướng Chính phủ làm nhiệm vụ theo sự phân công của chủ thể nào, chịu trách nhiệm cá nhân về nhiệm vụ được phân công trước chủ thể nào, đồng thời cùng các thành viên khác chịu trách nhiệm tập thể về hoạt động của Chính phủ?",o:["Theo phân công của Thủ tướng Chính phủ và chịu trách nhiệm trước Quốc hội về nhiệm vụ được phân công","Theo phân công của Chủ tịch nước và chịu trách nhiệm trước Thủ tướng Chính phủ về nhiệm vụ được phân công","Theo phân công của Chính phủ và chịu trách nhiệm trước Chủ tịch nước về nhiệm vụ được phân công","Theo phân công của Thủ tướng Chính phủ và chịu trách nhiệm trước Thủ tướng Chính phủ về nhiệm vụ được phân công"],c:3},{id:"vb05-89",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"khoản 2 Điều l5 Luật Tổ chức Chính phủ năm 2025,",gt:"Khi Thủ tướng vắng mặt, một Phó Thủ tướng được Thủ tướng ủy nhiệm thay mặt lãnh đạo công tác của Chính phủ; không xác định theo thâm niên hay do Chủ tịch nước chỉ định.",mn:'Nhớ cụm "Ủy nhiệm mới được thay”: chỉ người được Thủ tướng ủy nhiệm mới thay mặt, như người được giám đốc ký giấy ủy quyền mới được điều hành khi giám đốc di vắng.',t:"m",q:"Trường hợp Thủ tướng Chính phủ vắng mặt (ví dụ đi công tác ngoài nước) mà công tác của Chính phủ vẫn cần được lãnh đạo liên tục, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), ai thay mặt Thủ tướng Chính phủ lãnh đạo công tác của Chính phủ?",o:["Phó Thủ tướng có thâm niên cao nhất","Bộ trưởng, Chủ nhiệm Văn phòng Chính phủ","Phó Thủ tướng do Thủ tướng ủy nhiệm","Chủ tịch nước chỉ định người thay"],c:2},{id:"vb05-90",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 4 Điều 14 Luật TỔ chức Chính phủ năm 2025.",gt:"Thủ tướng thay mặt Chính phủ ký văn bản của Chính phủ hoặc ủy quyền cho thành viên Chính phủ ký thay; không ủy quyền cho cán bộ không phải thành viên Chính phủ.",mn:'Nhớ cụm "Ký thay - phải là thành viên Chính phủ”: người được ủy quyền ký phải thuộc thành viên Chính phủ, như chỉ trưởng nhóm mới được ký thay trưởng phòng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), các văn bản của Chính phủ được ban hành trên cơ sở thảo luận và quyết định của tập thể Chính phủ. Về việc ký các văn bản của Chính phủ, Thủ tướng Chính phủ thực hiện theo cách nào dưới đây?",o:["Thay mặt Chính phủ hoặc ủy quyền cho Chánh Văn phòng Chính phủ thay mặt Chính phủ ký các văn bản","Thay mặt Chính phủ hoặc ủy quyền cho Chủ tịch Ủy ban nhân dân cấp tỉnh ký các văn bản","Thay mặt Chính phủ hoặc ủy quyền cho thành viên Chính phủ thay mặt Chính phủ ký các văn bản của Chính phủ","Thay mặt Chính phủ và không được ủy quyền cho người khác ký các văn bản của Chính phủ"],c:2},{id:"vb05-91",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm d khoản 4 Điều 13 Luật TỔ chức Chính phủ năm 2025.",gt:"Thủ tướng lãnh đạo, chỉ đạo Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân cấp tỉnh thực hiện pháp luật và chương trình, kế hoạch, chiến lược của Chính phủ trên các lĩnh vực quản lý.",mn:'Nhớ cụm "Chương trình - kế hoạch - chiến lược”: ba thứ Chính phủ vạch ra để địa phương làm theo, như chương trình, kế hoạch, chiến lược của một doanh nghiệp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ lãnh đạo, chỉ đạo Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân cấp tỉnh thực hiện quy định của pháp luật và [......... ] của Chính phủ trên lĩnh vực quản lý về kinh tế, văn hóa, xã hội, giáo dục, y tế, khoa học, công nghệ, môi trường, thông tin, truyền thông, đối ngoại và hội nhập quốc tế, quốc phòng, an ninh quốc gia, trật tự, an toàn xã hội.",o:["chủ trương, đề án, dự án","chương trình, kế hoạch, chiến lược","kế hoạch, quy hoạch, chính sách","chương trình, dự án, chỉ tiêu"],c:1},{id:"vb05-92",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm a khoản 5 Điều 13 Luật TỔ chức Chính phủ năm 2025. Luáạt TCCP 2025 Trong 39",gt:"Thủ tướng quản lý và điều hành hoạt động của hệ thống hành chính nhà nước từ trung ương đến địa phương, không giới hạn ở khối cơ quan trung ương hay cấp tỉnh.",mn:'Nhớ cụm "Một mạch từ trên xuống”: hệ thống hành chính chạy từ trung ương đến địa phương, như động nước chảy từ đâu nguồn đến cuối nguồn.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi lãnh đạo và chịu trách nhiệm về hoạt động của hệ thống hành chính nhà nước, Thủ tướng Chính phủ quản lý và điều hành hoạt động của hệ thống này trong quá trình phục vụ Nhân dân và thực hiện nhiệm vụ phát triển kinh tế, văn hóa, xã hội, quốc phòng, an ninh. Phạm vi quản lý, điều hành đó được xác định như thế nào?",o:["Từ trung ương đến địa phương","Từ trung ương đến cấp tỉnh, không bao gồm cấp xã, chỉ đạo thông qua Ủy ban nhân dân cấp tỉnh và các cơ quan chuyên môn","Các Bộ, cơ quan ngang Bộ","Từ cấp tỉnh đến cấp xã"],c:0},{id:"vb05-93",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 và khoản 6 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:'Đối với Bộ trưởng, Thủ tướng trình Quốc hội phê chuẩn đề nghị bổ nhiệm, miễn nhiệm, cách chức; Thủ tướng chi trực tiếp bổ nhiệm, miễn nhiệm đối với Thứ trưởng và phê chuẩn việc bầu lãnh đạo Ủy ban nhân dân cấp tỉnh. ® Miẹo nhớ: Nhớ cụm "Bộ trưởng - Quốc hội phê chuẩn; Thứ trưởng - Thủ tướng bổ nhiệm”: cấp Bộ trưởng phải qua Quốc hội, con Thứ trưởng thì Thủ tướng quyết định.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nội dung nào sau đây KHÔNG thuộc nhiệm vụ, quyền hạn của Thủ tướng Chính phủ?",o:["Bổ nhiệm, miễn nhiệm, tạm đình chỉ công tác, cách chức, cho từ chức Thứ trưởng, chức vụ tương đương thuộc Bộ","Quyết định các vấn đề khi còn có ý kiến khác nhau giữa các Bộ trưởng, Thủ trưởng cơ quan ngang Bộ","Trực tiếp quyết định bổ nhiệm, miễn nhiệm, cách chức Bộ trưởng, Thủ trưởng cơ quan ngang Bộ mà không cần trình Quốc hội phê chuẩn","Phê chuẩn việc bầu, miễn nhiệm Chủ tịch, Phó Chủ tịch Ủy ban nhân dân cấp tỉnh"],c:2},{id:"vb05-94",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Điểm ạa khoản 6 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Trong thời gian giữa hai kỳ họp Hội đồng nhân dân cấp tỉnh, khi khuyết Chủ tịch Ủy ban nhân dân cấp tỉnh thì Thủ tướng Chính phủ quyết định giao quyền Chủ tịch.",mn:'Nhớ cụm "Khuyêết người đứng đầu tỉnh — Thủ tướng giao quyền”: Thủ tướng giao quyền để tính không bị gián đoàn, như tống công ty cử người điều hành tạm thời cho chi nhánh. Luật TCCP 2025 Trong 4U',t:"m",q:"Trường hợp tình A khuyết Chủ tịch Ủy ban nhân dân cấp tỉnh trong thời gian giữa hai kỳ họp Hội đồng nhân dân cấp tỉnh, chưa thể tiến hành bầu người thay thế ngày, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), chủ thể nào có thẩm quyền quyết định giao quyền Chủ tịch Ủy ban nhân dân cấp tỉnh?",o:["Ủy ban Thường vụ Quốc hội, sau khi có đề nghị của Chủ tịch nước và ý kiến của Bộ trưởng Bộ Nội vụ","Chủ tịch nước","Thủ tướng Chính phủ","Hội đồng nhân dân cấp tỉnh"],c:2},{id:"vb05-95",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ trưởng không tự bãi bỏ nghị quyết của Hội đồng nhân dân mà chi kiến nghị với Thủ tướng Chính phủ đình chỉ việc thi hành nghị quyết trái Hiến pháp, luật và văn bản cấp trên.",mn:'Nhớ cụm "Bộ trưởng kiến nghị — Thủ tướng định chi": Bộ trưởng chỉ kiến nghị, người có quyền đình chỉ là Thủ tướng, như nhân viên phát hiện sai sót thì báo lên cấp trên xử lý.',t:"m",q:"Trường hợp Bộ trưởng Bộ X phát hiện một nghị quyết của Hội đồng nhân dân cấp tỉnh trái với Hiến pháp, luật và văn bản của cơ quan nhà nước cấp trên về ngành, lĩnh vực mà Bộ do mình đứng đầu chịu trách nhiệm quản lý, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng có quyền thực hiện biện pháp nào?",o:["Trực tiếp bãi bỏ nghị quyết đó và thông báo cho Hội đồng nhân dân cấp tỉnh","Kiến nghị với Thủ tướng Chính phủ đình chỉ việc thi hành nghị quyết đó theo thẩm quyền","Giải tán Hội đồng nhân dân cấp tỉnh và yêu cầu bầu cử lại","Kiến nghị với Chủ tịch nước bãi bỏ nghị quyết do"],c:1},{id:"vb05-96",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Khoản 1 Điều 15 Luật TỔ chức Chính phủ năm 2025.",gt:"Phó Thủ tướng vừa chịu trách nhiệm với Thủ tướng về phân việc được giao, vừa cùng các thành viên khác chịu trách nhiệm tập thể về hoạt động của Chính phủ.",mn:'Nhớ cụm "Việc riêng báo Thủ tướng, việc chung cùng gánh”: phân chung là trách nhiệm tập thể, như cả đối cùng chịu trách nhiệm về kết quả chung của đội.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), ngoài việc chịu trách nhiệm trước Thủ tướng Chính phủ về nhiệm vụ được phân công, Phó Thủ tướng Chính phủ còn phải thực hiện trách nhiệm nào dưới đây đối với hoạt động chung của Chính phủ?",o:["Cùng các thành viên khác chịu trách nhiệm tập thể","Chịu trách nhiệm cá nhân thay cho Thủ tướng Chính phủ trước Quốc hội về mọi quyết định của Chính phủ trong nhiệm kỳ","Chịu trách nhiệm trước Chủ tịch nước","Chịu trách nhiệm trước Ủy ban Thường vụ Quốc hội"],c:0},{id:"vb05-97",s:"CHƯƠNG II - MỤC 2: THỦ TƯỚNG CHÍNH PHỦ, PHÓ THỦ TƯỚNG CHÍNH PHỦ 63/2025/QH15.",cc:"Diểm ở khoản 4 Điều 12 Luật Tổ chức Chính phủ năm 2025.",gt:"Việc lãnh đạo, chỉ đạo, kiểm tra và xử lý vi phạm trong thực hiện Hiến pháp và pháp luật của Thủ tướng được thực hiện trong phạm vi toàn quốc.",mn:'Nhớ cụm "Kiểm tra pháp luật - toàn quốc”: Thủ tướng nhìn bao quát phạm vi toàn quốc, như người điều hành giao thông giám sát toàn bộ mạng lưới dưỡng. Luật FCCP 2025 lrung i2 Phạm vi: vị trí, chức năng của Bộ trưởng (Điều 16); nhiệm vụ, quyền hạn, trách nhiệm với tư cách thành viên Chính phủ (Điều 17, 18); với tư cách người đứng đầu Bộ (Điều 19, 20); Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ (Điều 21); Bộ, cơ quan ngang Bộ (Điều 22): Văn phòng Chính phủ (Điều 23); cơ quan thuộc Chính phù (Điều 24). Đáp án đối chiếu Luật số 63/2025/QH15.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ lãnh đạo, chỉ đạo, kiểm tra và xử lý các vi phạm trong quá trình triển khai thực hiện Hiến pháp và pháp luật trong |........ ], thuộc nhiệm vụ, quyền hạn cụ thể khi lãnh đạo công tác của Chính phủ.",o:["phạm vi toàn quốc","phạm vi các Bộ, cơ quan ngang Bộ Luáạt TCCP 2025 Trong 41","phạm vi cơ quan hành chính trung ương","phạm vi cấp tỉnh trở lên"],c:0},{id:"vb05-98",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Điều I6 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ trưởng là thành viên Chính phủ (tham gia quyết định tập thể) và đồng thời là người đứng đầu Bộ, cơ quan ngang Bộ (lãnh đạo công tác của Bộ).",mn:'Nhớ cụm "Một người hai vai": vai thành viên Chính phủ và vai người đứng đầu Bộ, như một trường phòng vừa là thành viên ban lãnh đạo công ty, vừa là người đứng đầu phòng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng, Thủ trưởng cơ quan ngang Bộ giữ đồng thời hai tư cách trong bộ máy nhà nước. Hai tư cách đó được xác định như thế nào?",o:["Là đại biểu Quốc hội và là người đứng đầu Bộ, cơ quan ngang Bộ, lãnh đạo công tác của Bộ, cơ quan ngang Bộ","Là thành viên Chính phủ và là người đứng đầu chính quyền địa phương, lãnh đạo công tác của Ủy ban nhân dân cấp tỉnh","Là thành viên Ủy ban Thường vụ Quốc hội và là người đứng đầu Bộ, cơ quan ngang Bộ, lãnh đạo công tác của Bộ","Là thành viên Chính phủ và là người đứng đầu Bộ, cơ quan ngang Bộ, lãnh đạo công tác của Bộ, cơ quan ngang Bộ"],c:3},{id:"vb05-99",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Điều 16 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ quản lý nhà nước về một hoặc một số ngành, lĩnh vực và dịch vụ công thuộc ngành, lĩnh vực được phân công, trong phạm vi toàn quốc. Luật TCCP 2025 Iruong 43",mn:'Nhớ cụm "Một hoặc một số”: Bộ không quản lý tất cả, chỉ phụ trách một hoặc một số ngành, lĩnh vực, như mỗi phòng ban có mảng việc riêng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chịu trách nhiệm quản lý nhà nước về....... ] và dịch vụ công thuộc ngành, lĩnh vực được phân công; tổ chức thi hành và theo dõi việc thi hành pháp luật liên quan đến ngành, lĩnh vực trong phạm vi toàn quốc.",o:["một hoặc một số ngành, lĩnh vực","toàn bộ các ngành, lĩnh vực","một ngành, lĩnh vực duy nhất","một hoặc một số vùng, địa phương"],c:0},{id:"vb05-100",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"khoản 1 và khoản 2 Điều 17; điểm a khoản 4 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Việc triệu tập và chủ trì phiên họp là nhiệm vụ của Thủ tướng Chính phủ; Bộ trưởng với tư cách thành viên chỉ tham dự, giải quyết công việc chung, biểu quyết và đề xuất.",mn:'Nhớ cụm "Chủ trì là của Thủ tướng”: Bộ trưởng tham dự và biểu quyết, còn triệu tập, chủ trì thuộc về Thủ tướng, như người dự họp không phải là người chủ tọa cuộc họp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là thành viên Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ tham dự phiên họp Chính phủ. Nhiệm vụ nào sau đây KHÔNG thuộc nhiệm vụ, quyền hạn của Bộ trưởng với tư cách thành viên Chính phủ tại phiên họp?",o:["Triệu tập và chủ trì các phiên họp của Chính phủ","Tham dự phiên họp Chính phủ và tham gia giải quyết công việc chung của tập thể Chính phủ","Tham gia biểu quyết tại phiên họp, cùng tập thể Chính phủ quyết định vấn đề thuộc thẩm quyền của Chính phủ","Đề xuất với Chính phủ, Thủ tướng Chính phủ chủ trương, chính sách, cơ chế, văn bản pháp luật cần thiết"],c:0},{id:"vb05-101",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản Ì Điều 18 Luật Tổ chức Chính phủ năm 2025.",gt:"Với tư cách thành viên Chính phủ. Bộ trưởng chịu trách nhiệm cá nhân trước Thủ tướng Chính phù, Chính phủ và Quốc hội; con tư cách người đứng đầu Bộ thì trước Thủ tướng và Chính phủ.",mn:'Nhớ cụm "Thành viên thì có Quốc hội”: tư cách thành viên Chính phủ chịu trách nhiệm thêm trước Quốc hội, như người vừa là nhân viên vừa là cơ động thì phải báo cáo thêm với đại hội có động. Luut TCCP "25 lrung k1',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là thành viên Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chịu trách nhiệm cá nhân về ngành, lĩnh vực được phân công quản lý trước những chủ thể nào (khác với trách nhiệm khi là người đứng đầu Bộ)?",o:["Thủ tướng Chính phủ và Chủ tịch nước","Chính phủ và Ủy ban Thường vụ Quốc hội","Thủ tướng Chính phủ, Chính phủ và Quốc hội","Quốc hội và Hội đồng nhân dân cấp tỉnh, đồng thời báo cáo bằng văn bản với Ủy ban trung ương Mặt trận Tổ quốc Việt Nam"],c:2},{id:"vb05-102",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 1 và khoản 8 Điều 19 Luật TỔ chức Chính phủ năm 2025.",gt:"Bộ trưởng chỉ có quyền kiến nghị Thủ tướng đình chỉ nghị quyết của Hội đồng nhân dân cấp tỉnh trái pháp luật; không có quyền trực tiếp bãi bỏ nghị quyết do.",mn:'Nhớ cụm "Kiến nghị chủ không tự bãi bỏ": Bộ trưởng kiến nghị, Thủ tướng đình chỉ, như nhân viên đề xuất còn quyết định do lãnh đạo cấp trên.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là người đứng đầu Bộ, Bộ trưởng có thẩm quyền đối với nghị quyết của Hội đồng nhân dân cấp tỉnh trái pháp luật về ngành, lĩnh vực mình quản lý. Nội dung nào sau đây KHÔNG đúng với thẩm quyền đô?",o:["Kiến nghị với Thủ tướng Chính phủ đình chỉ việc thi hành nghị quyết của Hội đồng nhân dân cấp tỉnh trái với Hiến pháp, luật","Trực tiếp bãi bỏ nghị quyết của Hội đồng nhân dân cấp tỉnh trái với Hiến pháp, luật và văn bản của cơ quan nhà nước cấp trên","Đề nghị Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân cấp tỉnh đình chỉ việc thi hành hoặc bãi bỏ quy định trái với văn bản về ngành, lĩnh vực được phân công","Báo cáo Thủ tướng Chính phủ quyết định khi Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân cấp tỉnh không chấp hành đề nghị"],c:1},{id:"vb05-103",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoan I Điều 19; điểm b khoản 6 Điều 13 Luật Tổ chức Chính phù năm 2025.",gt:"Bộ trưởng đề nghị Thủ tướng Chính phủ bổ nhiệm, miễn nhiệm, tạm đình chỉ công tác, cách chức, cho từ chức Thứ trưởng; Thủ tướng là người quyết định.",mn:'Nhớ cụm "Thứ trưởng - Bộ trưởng đề nghị, Thủ tướng quyết”: Bộ trưởng đề nghị, Thủ tướng quyết định, như trường phòng đề xuất nhân sự nhưng giám đốc mới ký quyết định.',t:"m",q:"Trường hợp Bộ trưởng Bộ X nhận thấy một Thứ trưởng của Bộ vi phạm quy chế làm việc và cán tạm đình chỉ công tác Thứ trưởng đó, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng thực hiện theo cách nào?",o:["Trực tiếp quyết định tạm đình chỉ công tác Thứ trưởng, đồng thời báo cáo Thủ tướng Chính phủ và Ủy ban Thường vụ Quốc hội để theo dõi","Đề nghị Chủ tịch nước quyết định","Đề nghị Quốc hội quyết định","Đề nghị Thủ tướng Chính phủ quyết định"],c:3},{id:"vb05-104",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 2 Điều 21 Luật Tổ chức Chính phủ năm 2025.",gt:"Mức chung là số lượng Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ không quá 05; ba Bộ Quốc phòng, Công an, Ngoại giao không quá 06.",mn:'Nhớ cụm "05 chung - 06 cho ba Bộ”: mức chung 05, bà Bộ đặc thù được thêm một, như ban thường ngôi năm người, bản lớn ngơi sau.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), số lượng Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ không quá [......... I, Bộ Quốc Luật 1ICCP 2025 Irongq 45 phòng, Bộ Công an, Bộ Ngoại giao không quá 06, trừ trường hợp do yêu cầu điều động, luân chuyển cán bộ của cấp có thẩm quyền.",o:["04","07","03","05"],c:3},{id:"vb05-105",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 2 Điều 21 Luật TỔ chức Chính phủ năm 2025.",gt:"Ba Bộ có số lượng Thứ trưởng không quá 06 là Bộ Quốc phòng, Bộ Công an, Bộ Ngoại giao; các Bộ khác không quá 05.",mn:'Nhớ cụm "Quốc phòng - Công an - Ngoại giao”: ba Bộ thuộc lĩnh vực an ninh - đối ngoại, nhờ theo thứ tự "bảo vệ trong, bảo vệ ngoài, giao thiệp ngoài”.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khác với mức chung về số lượng Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ không quá 05, nhóm Bộ nào sau đây được có số lượng Thứ trưởng không quá 06?",o:["Quốc phòng, Công an, Ngoại giao","Quốc phòng, Công an, Nội vụ","Quốc phòng, Ngoại giao, Tư pháp","Công an, Ngoại giao, Tài chính"],c:0},{id:"vb05-106",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"khoản 1 Điều 21 Luật Tổ chức Chính phủ năm 2025.",gt:"Thứ trưởng giúp Bộ trưởng thực hiện nhiệm vụ do Bộ trưởng phân công và chịu trách nhiệm trước Bộ trưởng về nhiệm vụ được phân công, không phải trước Thủ tướng hay Quốc hội. Luật TCCP 2025 Trung 4b",mn:'Nhớ cụm "Ai giao việc, báo cáo người đó”: Thủ trưởng chịu trách nhiệm trước Bộ trưởng. như phó phòng chịu trách nhiệm trước trưởng phòng đã phân công.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thứ trưởng, Phó Thủ trưởng cơ quan ngang Bộ giúp Bộ trưởng, Thủ trưởng cơ quan ngang Bộ thực hiện nhiệm vụ do Bộ trưởng phân công. Thứ trưởng chịu trách nhiệm về nhiệm vụ được phân công trước chủ thể nào?",o:["Thủ tướng Chính phủ, vì Thủ tướng là người bổ nhiệm Thứ trưởng theo đề nghị của Bộ trưởng","Quốc hội","Chính phủ","Bộ trưởng, Thủ trưởng cơ quan ngang Bộ"],c:3},{id:"vb05-107",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoan Ì Điều 22 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ, cơ quan ngang Bộ là cơ quan của Chính phủ, thực hiện chức năng quản lý nhà nước theo ngành, lĩnh vực trong phạm vi toàn quốc.",mn:'Nhớ cụm "Bộ thuộc Chính phủ": Bộ là cơ quan của Chính phủ, như phòng chuyên môn là bộ phận của công ty.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ, cơ quan ngang Bộ thực hiện chức năng quản lý nhà nước về một hoặc một số ngành, lĩnh vực và dịch vụ công thuộc ngành, lĩnh vực được phân công trong phạm vi toàn quốc. Bộ, cư quan ngang Bộ là cơ quan của chủ thể nào?",o:["Cơ quan của Chính phủ","Cơ quan của Quốc hội, do Quốc hội thành lập và quyết định cơ cấu tổ chức theo đề nghị của Thủ tướng Chính phủ","Cơ quan của Chủ tịch nước","Cơ quan của chính quyền địa phương"],c:0},{id:"vb05-108",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Nhoản 2 Diện 22 và khoản 2 Điều 2 Luật Tổ chức Chính phủ năm 2025.",gt:"Quốc hội quyết định việc thành lập, bãi bỏ Bộ; con Chính phủ quy định cụ thể chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của từng Bộ. cơ quan ngang Bộ.",mn:'Nhớ cụm "Lập, bỏ — Quốc hội; chức năng - Chính phủ”: thành lập do Quốc hội, chức năng, cơ cấu do Chính phủ, như hội đồng quản trị cho mở phòng, còn giám đốc quy định nhiệm vụ phòng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), việc thành lập, bãi bỏ Bộ, cư quan ngang Bộ do Chính phủ trình Quốc hội quyết định, còn việc quy định cụ thể chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của từng Bộ, cơ quan ngang Bộ thuộc thẩm quyền của chủ thể nào?",o:["Quốc hội, trên cơ sở đề nghị của Thủ tướng Chính phủ và thẩm tra của các Ủy ban của Quốc hội","Chính phủ","Thủ tướng Chính phủ","Chủ tịch nước"],c:1},{id:"vb05-109",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản Ì Điều 23 Luật Tổ chức Chính phủ năm 2025.",gt:"Văn phòng Chính phủ là bộ máy giúp việc của Chính phủ, Thủ tướng Chính phủ với chức năng tham mưu tổng hợp, giúp việc; không phải cơ quan thuộc Chính phủ hay cơ quan ngang Bộ.",mn:'Nhớ cụm "Văn phòng = giúp việc": Văn phòng Chính phủ chỉ tham mưu tổng hợp, giúp việc, như văn phòng công ty hỗ trợ bạn giám đốc chứ không điều hành ngành.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Văn phòng Chính phủ là một thiết chế trong bộ máy của Chính phủ. Chức năng của Văn phòng Chính phủ được xác định như thế nào?",o:["Là bộ máy giúp việc của Chính phủ, Thủ tướng Chính phủ, có chức năng tham mưu tổng hợp, giúp việc cho Chính phủ, Thủ tướng Chính phủ Luật FCCP 2025 lrung","Là cơ quan thuộc Chính phủ, có chức năng thực thi chính sách, phục vụ quản lý nhà nước, cung ứng dịch vụ công","Là bộ máy giúp việc của Quốc hội, có chức năng tham mưu tổng hợp, giúp việc cho Quốc hội, Ủy ban Thường vụ Quốc hội","Là cơ quan ngang Bộ, có chức năng quản lý nhà nước về một hoặc một số ngành, lĩnh vực được phân công"],c:0},{id:"vb05-110",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"khoản 2 Điều 23 Luật TỔ chức Chính phủ năm 2025.",gt:"Văn phòng Chính phủ do Bộ trưởng, Chủ nhiệm Văn phòng Chính phủ đứng đầu.",mn:'Nhớ cụm "Bộ trưởng kiêm Chủ nhiệm": người đứng đầu có tên gọi Bộ trưởng, Chủ nhiệm, không gọi là Chánh Văn phòng hay Tổng Thư ký.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Văn phòng Chính phủ là bộ máy giúp việc của Chính phủ, Thủ tướng Chính phủ, có chức năng tham mưu tổng hợp. Chức danh của người đứng đầu Văn phòng Chính phủ được quy định như thế nào?",o:["Chánh Văn phòng Chính phủ, do Thủ tướng Chính phủ bổ nhiệm và chịu trách nhiệm trước Quốc hội về hoạt động của Văn phòng","Tổng Thư ký Chính phủ","Bộ trưởng, Chủ nhiệm Văn phòng Chính phủ","Phó Thủ tướng thường trực"],c:2},{id:"vb05-111",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 1 Điều 24 Luật Tổ chức Chính phủ năm 2025.",gt:"Cơ quan thuộc Chính phủ do Chính phủ thành lập. có chức năng thực thi chính sách, phục vụ quản lý nhà nước, cung ứng dịch vụ công; chức năng quản lý nhà nước theo ngành là của Bộ.",mn:'Nhớ cụm "Thuộc Chính phủ - thực thi, phục vụ, cung ứng”: ba động từ thực thi, phục vụ, cung tưng, như đơn vị sự nghiệp trực thuộc làm việc thực hiện chủ không quản lý ngành.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), cơ quan thuộc Chính phủ là cơ quan do chủ thể nào thành lập và thực hiện chức năng gì?",o:["Do Chính phủ thành lập, thực hiện chức năng quản lý nhà nước về một hoặc một số ngành, lĩnh vực trong phạm vi toàn quốc","Do Thủ tướng Chính phủ thành lập, thực hiện chức năng thực thi chính sách, phục vụ quản lý nhà nước, cung ứng dịch vụ công","Do Quốc hội thành lập, thực hiện chức năng tham mưu tổng hợp, giúp việc cho Chính phủ, Thủ tướng Chính phủ","Do Chính phủ thành lập, thực hiện chức năng thực thi chính sách, phục vụ quản lý nhà nước, cung ứng dịch vụ công Luật FCCP 2025 lrung!ö"],c:3},{id:"vb05-112",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 3 Điều 24 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ trưởng cơ quan thuộc Chính phủ chịu trách nhiệm trước Chính phủ, Thủ tướng Chính phủ về nhiệm vụ, quyền hạn được giao.",mn:'Nhớ cụm "Thuộc Chính phủ thì báo cáo Chính phủ”: cơ quan thuộc Chính phủ thì chịu trách nhiệm trước Chính phủ, Thủ tướng, như đơn vị trực thuộc báo cáo cho công ty mẹ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ trưởng cơ quan thuộc Chính phủ thực hiện nhiệm vụ và quyền hạn theo quy định của Chính phủ. Về nhiệm vụ và quyền hạn được giao, Thủ trưởng cơ quan thuộc Chính phủ chịu trách nhiệm trước chủ thể nào?",o:["Bộ trưởng Bộ Nội vụ, người quản lý nhà nước về tổ chức bộ máy của các cơ quan thuộc Chính phủ","Quốc hội, Chủ tịch nước","Chính phủ, Thủ tướng Chính phủ","Hội đồng nhân dân cấp tỉnh"],c:2},{id:"vb05-113",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 2 Điều 19 Luật TỔ chức Chính phủ năm 2025. Luật TCCP 2025 Trung 49",gt:"Bộ trưởng ban hành văn bản quy phạm pháp luật theo thẩm quyền (không cần ủy quyền) và ban hành chiến lược, quy hoạch, kế hoạch, chính sách phát triển ngành, lĩnh vực được phân công.",mn:'Nhớ cụm "Văn bản theo thẩm quyền, chiến lược theo ngành”: Bộ trưởng ban hành văn bản theo thẩm quyền và chiến lược cho ngành mình phụ trách, như trưởng bộ phận xây dựng kế hoạch cho mạng việc của mình.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), khi thực hiện chức năng, nhiệm vụ quản lý nhà nước đối với ngành, lĩnh vực được phân công, Bộ trưởng với tư cách là người đứng đầu Bộ ban hành những loại văn bản nào, theo căn cứ nào?",o:["Văn bản quy phạm pháp luật theo ủy quyền của Chính phủ; chiến lược, quy hoạch, kế hoạch, chính sách phát triển ngành, lĩnh vực được phân công","Văn bản quy phạm pháp luật theo thẩm quyền; chiến lược, quy hoạch, kế hoạch, chính sách phát triển ngành, lĩnh vực được phân công","Văn bản quy phạm pháp luật theo thẩm quyền; chiến lược, quy hoạch, kế hoạch, chính sách phát triển kinh tế - xã hội của cả nước","Văn bản quy phạm pháp luật theo thẩm quyền; chiến lược, quy hoạch, kế hoạch, chính sách phát triển của từng địa phương thuộc ngành, lĩnh vực"],c:1},{id:"vb05-114",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 1 Điều 20 Luật Tổ chức Chính phủ năm 2025.",gt:"Với tư cách người đứng đầu Bộ, Bộ trưởng chịu trách nhiệm cá nhân trước Thủ tướng Chính phủ, Chính phủ; trách nhiệm trước Quốc hội gắn với tư cách thành viên Chính phủ.",mn:'Nhớ cụm "Đứng đầu Bộ - hai địa chỉ”: người đứng đầu Bộ báo cáo Thủ tướng và Chính phủ, còn thêm Quốc hội khi xét tư cách thành viên Chính phủ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), với tư cách là người đứng đầu Bộ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chịu trách nhiệm cá nhân về kết quả, hiệu lực, hiệu quả hoạt động của Bộ và về các quyết định của mình trước những chủ thể nào?",o:["Thủ tướng Chính phủ, Chính phủ và Quốc hội, đồng thời báo cáo trước Hội đồng nhân dân các cấp theo từng kỳ họp","Thủ tướng Chính phủ, Chính phủ","Quốc hội, Chủ tịch nước","Hội đồng nhân dân, Mặt trận Tổ quốc Việt Nam"],c:1},{id:"vb05-115",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 6 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Khi kiến nghị đôi với Bộ trưởng khác không được chấp thuận thì Bộ trưởng báo cáo Thủ tướng Chính phủ quyết định.",mn:'Nhớ cụm "Hai Bộ bất động - Thủ tướng quyết”: tranh chấp giữa hai Bộ thì Thủ tướng quyết định, như hai phòng không thống nhất thì giám đốc quyết.',t:"m",q:"Trường hợp Bộ trưởng Bộ A kiến nghị Bộ trưởng Bộ B đình chỉ việc thi hành hoặc bãi bỏ quy định do Bộ B ban hành trái với Hiến pháp, luật về ngành, lĩnh vực của Bộ A quản lý, nhưng kiến nghị không được chấp thuận, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng Bộ A báo cáo như thế nào?",o:["Báo cáo Chính phủ để Chính phủ biểu quyết và quyết định tại phiên họp gần nhất","Báo cáo Chủ tịch nước để Chủ tịch nước xem xét và quyết định","Báo cáo Ủy ban Thường vụ Quốc hội để cho ý kiến và giải quyết","Báo cáo Thủ tướng Chính phủ đề Thủ tướng Chính phủ quyết định"],c:3},{id:"vb05-116",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 8 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Nếu Ủy ban nhân dân, Chủ tịch Ủy ban nhân dân cấp tỉnh không chấp hành thì Bộ trưởng báo cáo Thủ tướng Chính phủ quyết định; Bộ trưởng không trực tiếp bãi bỏ.",mn:'Nhớ cụm "Địa phương không chấp hành - báo Thủ tướng”: Bộ trưởng đề nghị, không chấp hành thì báo cáo Thủ tướng, như nhân viên báo cáo lên giám đốc khi đơn vị khác không thực hiện.',t:"m",q:"Trường hợp Bộ trưởng Bộ X đề nghị Ủy ban nhân dân cấp tỉnh đình chỉ việc thi hành hoặc bãi bỏ quy định trái với văn bản về ngành, lĩnh vực được Luật TCCP 2025 Trong 50 phân công, nhưng Ủy ban nhân dân cấp tỉnh không chấp hành, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng xử lý như thế nào?",o:["Báo cáo Thủ tướng Chính phủ quyết định","Trực tiếp ra quyết định bãi bỏ quy định đó và yêu cầu Hội đồng nhân dân cấp tỉnh xem xét trách nhiệm của Chủ tịch Ủy ban nhân dân","Đề nghị Chủ tịch nước xem xét","Tự đình chỉ việc thi hành quy định"],c:0},{id:"vb05-117",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"khuôn 2 Điều 18 Luật TỔ chit Chính phủ năm 2025.",gt:"Bộ trưởng với tư cách thành viên Chính phủ báo cáo công tác trước Chính phủ, Thủ tướng. báo cáo trước Nhân dân, giải trình, trả lời chất vấn của đại biểu Quốc hội: không báo cáo trước Hội đồng nhân dân cấp tỉnh.",mn:'Nhớ cụm "Báu cáo lên và ra Nhân dân”: báo cáo lên Chính phủ, ra Nhân dân, trả lời Quốc hội, không có Hội đồng nhân dân cấp tỉnh.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là thành viên Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ thực hiện trách nhiệm báo cáo, giải trình. Nội dung nào sau đây KHÔNG phải là trách nhiệm của Bộ trưởng với tư cách thành viên Chính phủ?",o:["Báo cáo công tác trước Hội đồng nhân dân cấp tỉnh","Báo cáo công tác trước Chính phủ, Thủ tướng Chính phủ","Thực hiện chế độ báo cáo trước Nhân dân về những vấn đề quan trọng thuộc trách nhiệm quản lý","Giải trình, trả lời chất vấn của đại biểu Quốc hội"],c:0},{id:"vb05-118",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"khoản 2 Điều 17 Luật Tổ chức Chính phủ năm 2025,",gt:"Bộ trưởng chịu trách nhiệm về toàn bộ nội dung và tiến độ trình đề án, dự án, văn bản pháp luật được giao, tức cả chất lượng nội dung lần thời hạn trình.",mn:'Nhớ cụm "Nội dung công tiến độ”: phải đảm bảo cá nội dung lẫn tiến độ, như nộp bài phái đúng ý và đúng hạn.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng với tư cách là thành viên Chính phủ đề xuất với Chính phủ, Thủ tướng Chính phủ chủ trương, chính sách, cơ chế, văn bản pháp luật cần thiết thuộc thẩm quyền của Chính phủ, Thủ tướng Chính phủ; chịu trách nhiệm về [........ ] trình đề án, dự án, văn bản pháp luật được giao.",o:["nội dung nhưng không về tiến độ","toàn bộ nội dung và tiến độ","tiến độ nhưng không về nội dung","kết quả thi hành sau khi ban hành Luật FCCP 2025 lrung 51"],c:1},{id:"vb05-119",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 7 Điều 19 Luật Tổ chức thính phủ năm 2025.",gt:"Bộ trưởng chỉ đạo, hướng dẫn, kiểm tra Ủy ban nhân dân các cấp về nhiệm vụ thuộc ngành, Hnh vực được phân công hoặc do Chính phủ, Thủ tướng giao.",mn:'Nhớ cụm "Ngành mình hoặc cấp trên giao": chỉ đạo địa phương việc thuộc ngành mình hoặc việc Chính phủ, Thủ tướng giao, như trưởng bộ phận chỉ đạo chi nhánh theo máng việc của mình.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là người đứng đầu Bộ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chỉ đạo, hướng dẫn, kiểm tra Ủy ban nhân dân các cấp thực hiện nhiệm vụ công tác nào dưới đây?",o:["Nhiệm vụ công tác thuộc ngành, lĩnh vực được phân công hoặc Hội đồng nhân dân cùng cấp giao","Nhiệm vụ công tác thuộc ngành, lĩnh vực được phân công hoặc nhiệm vụ do Chính phủ, Thủ tướng Chính phủ giao","Nhiệm vụ công tác của địa phương theo đề nghị của Ủy ban nhân dân cấp tỉnh","Nhiệm vụ công tác thuộc ngành, lĩnh vực của Bộ khác hoặc Chính phủ, Thủ tướng Chính phủ giao"],c:1},{id:"vb05-120",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Điều 2: Điều 21 Luật Tổ chức Chính phủ năm 2025, Luật FCCP 2025 rung 52",gt:"Thành viên Chính phủ gồm Thủ tướng, các Phó Thủ tướng, các Bộ trưởng và Thủ trưởng cơ quan ngang Bộ: Thứ trưởng không phải là thành viên Chính phủ nền không biểu quyết tại phiên họp.",mn:'Nhớ cụm "Thứ trưởng không vào Chính phủ”: thành viên Chính phủ dụng ở Bộ trưởng, Thứ trưởng chỉ là người giúp việc, như phó phòng không có phiếu trong hội đồng của công ty.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nội dung nào sau đây KHÔNG đúng về Thủ trưởng, Phó Thủ trưởng cơ quan ngang Bộ?",o:["Số lượng Thứ trưởng không quá 05, riêng Bộ Quốc phòng, Bộ Công an, Bộ Ngoại giao không quá 06 theo mức quy định chung","Thứ trưởng giúp Bộ trưởng thực hiện nhiệm vụ do Bộ trưởng phân công cho từng Thứ trưởng","Thứ trưởng chịu trách nhiệm trước Bộ trưởng về nhiệm vụ mà Bộ trưởng đã phân công cho mình","Thứ trưởng là thành viên Chính phủ và tham gia biểu quyết tại phiên họp Chính phủ cùng với Bộ trưởng"],c:3},{id:"vb05-121",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 3 Điều 17 Luật Tổ chức Chính phủ năm 2025.",gt:"Công việc cụ thể theo ngành, lĩnh vực được thực hiện theo sự phân công của Chính phủ hoặc ủy quyền của Thủ tướng Chính phủ; không đảo vai trò hai chủ thể này.",mn:'Nhớ cụm "Chính phủ phân công, Thủ tướng ủy quyền": phân công thuộc về tập thể Chính phủ, ủy quyền là của Thủ tướng, như hội đồng giao việc còn giám đốc ủy quyền ký.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), với tư cách là thành viên Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ thực hiện công việc cụ thể theo ngành, lĩnh vực trên cơ sở nào, đồng thời chỉ đạo, hướng dẫn, kiểm tra việc thi hành pháp luật về ngành, lĩnh vực do?",o:["Theo ngành, lĩnh vực được Thủ tướng Chính phủ phân công hoặc Chính phủ ủy quyền","Theo ngành, lĩnh vực cụ thể được Chính phủ phân công hoặc được Thủ tướng Chính phủ ủy quyền","Theo ngành, lĩnh vực được Quốc hội phân công hoặc Chủ tịch nước ủy quyền","Theo ngành, lĩnh vực được Chính phủ phân công hoặc Bộ trưởng Bộ Nội vụ ủy quyền"],c:1},{id:"vb05-122",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 3 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ trưởng lãnh đạo, chỉ đạo và chịu trách nhiệm cá nhân về mọi mặt công tác của Bộ, cơ quan ngang Bộ, chủ không chỉ một mạng công tác riêng lễ,",mn:'Nhớ cụm "Đứng đầu là chịu mọi mặt”: người đứng đầu thì chịu trách nhiệm về mọi mặt công tác, như thuyền trưởng chịu trách nhiệm toàn bộ con tàu. Luật TCCP 2025 Trung 5.3',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là người đứng đầu Bộ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ lãnh đạo, chỉ đạo và chịu trách nhiệm cá nhân về nội dung nào dưới đây?",o:["Công tác chuyên môn của các đơn vị trực thuộc","Mọi mặt công tác của Bộ","Công tác tổ chức cán bộ và tài chính","Công tác đối ngoại và hợp tác quốc tế"],c:1},{id:"vb05-123",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 5 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Danh sách các cơ quan Bộ trưởng chủ động phối hợp gồm cơ quan của Đảng, Quốc hội, Chủ tịch nước, hai cơ quan tư pháp cao nhất, Kiểm toán nhà nước, Mặt trận Tổ quốc và các tổ chức chính trị - xã hội.",mn:'Nhớ cụm "Đang - Quốc hội - Chủ tịch nước - Tòa - Viện — Kiểm toán - Mặt trận”: thứ tự từ trên xuống, Kiểm toán nhà nước dung sau Viện kiểm sát.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chủ động phối hợp chặt chẽ với các cơ quan của Đảng, Quốc hội, Chủ tịch nước, Tòa án nhân dân tối cao, Viện kiểm sát nhân dân tối cao, [......... ], Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và cơ quan trung ương của tổ chức chính trị - xã hội.",o:["Kiểm toán nhà nước","Hội đồng Dân tộc","Thanh tra Chính phủ","Ngân hàng Nhà nước Việt Nam"],c:0},{id:"vb05-124",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Điều 24 Luật Tổ chức Chính phủ năm 2025.",gt:"Chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của cơ quan thuộc Chính phủ do Chính phủ quy định, không phải do Thủ tướng Chính phủ quy định.",mn:'Nhớ cụm "Cơ quan thuộc Chính phủ - Chính phủ quy định”: chủ thể quy định là Chính phủ (tập thể), không phải một mình Thủ tướng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), cơ quan thuộc Chính phủ do Chính phủ thành lập và hoạt động theo quy định của Luật này. Nhận định nào sau đây KHÔNG đúng về cơ quan thuộc Chính phủ?",o:["Cơ quan thuộc Chính phủ là cơ quan do Chính phủ thành lập, thực hiện chức năng thực thi chính sách, phục vụ quản lý nhà nước, cung ứng dịch vụ công","Thủ trưởng cơ quan thuộc Chính phủ chịu trách nhiệm trước Chính phủ, Thủ tướng Chính phủ về nhiệm vụ và quyền hạn được giao","Thủ tướng Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của cơ quan thuộc Chính phủ","Chính phủ quy định chi tiết các nội dung về cơ quan thuộc Chính phủ và quy định chức năng, nhiệm vụ, quyền hạn, cơ cấu tổ chức của cơ quan này"],c:2},{id:"vb05-125",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 2 Điều 21 Luật Tổ chức Chính phủ năm 2025.",gt:"Mức chung không quá 05 có ngoại lệ là trường hợp do yêu cầu điều động, luân chuyển cán bộ của cấp có thẩm quyền; việc tăng lền 06 vì lý do này là phù hợp.",mn:'Nhớ cụm "Quy định có ngoại lệ luân chuyển”: mức 05 là mức chung, nhưng luân chuyển cán bộ là ngoại lệ, như chỗ ngồi có hạn nhưng được thêm ghê khi có khách do cấp trên cử đến.',t:"m",q:"Trường hợp Bộ X hiện có 04 Thứ trưởng, nay cần tiếp nhận thêm 02 cán bộ do yêu cầu điều động, luân chuyển của cấp có thẩm quyền, nâng tổng số lên 06 Thứ trưởng, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), việc này được xem xét như thế nào?",o:["Phù hợp, vì mục không quá 05 có thế vượt khi do yêu cầu điều động, luân chuyển cán bộ của cấp có thẩm quyền Luáạt TCCP 2025 Trung 54","Không phù hợp, vì mục không quá 05 áp dụng cả khi có yêu cầu điều động, luân chuyển cán bộ","Không phù hợp, vì mục không quá 06 chí đánh riêng cho Bộ Quốc phòng, Bộ Công an, Bộ Ngoại giao","Phù hợp, vì các Bộ đều được có đến 06 Thứ trưởng khi Bộ trưởng đề nghị và Thủ tướng Chính phủ đồng ý"],c:0},{id:"vb05-126",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 6 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:'Bộ trưởng hướng dẫn, kiểm tra, phối hợp với các Bộ khác về nhiệm vụ công tác thuộc ngành, lĩnh vực được phân công: không can thiệp công tác nội bộ của Bộ khác. $ Miẹo nhớ: Nhớ cụm "Phối hợp theo ngành": phối hợp liên Bộ xoay quanh ngành, lĩnh vực được phân công, như các phòng phối hợp trên cùng một dự án.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng, Thủ trưởng cơ quan ngang Bộ hướng dẫn và kiểm tra, phối hợp với các Bộ, cơ quan ngang Bộ, cơ quan thuộc Chính phủ thực hiện [......... ] được phân công, đồng thời kiến nghị với Bộ trưởng khác đình chỉ việc thi hành hoặc bãi bỏ quy định trái pháp luật.",o:["nhiệm vụ nội bộ của từng Bộ","nhiệm vụ công tác của địa phương","nhiệm vụ do Hội đồng nhân dân giao","nhiệm vụ công tác thuộc ngành, lĩnh vực"],c:3},{id:"vb05-127",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 1 Điều 19 Luật TỔ chức Chính phủ năm 2025.",gt:"Bộ trưởng trình các vấn đề thuộc quản lý nhà nước về ngành, lĩnh vực theo phân công của Chính phủ và chỉ đạo của Thủ tướng Chính phủ.",mn:'Nhớ cụm "Chính phủ phân công, Thủ tướng chỉ đạo": hai chủ thể không đáo chỗ cho nhau, như hội đồng giao nhiệm vụ còn giám đốc chỉ đạo thực hiện.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là người đứng đầu Bộ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ trình Chính phủ, Thủ tướng Chính phủ xem xét, quyết định theo thẩm quyền hoặc trình cấp có thẩm quyền quyết định nội dung nào dưới đây?",o:["Các vấn đề thuộc phạm vi quản lý nhà nước về ngành, lĩnh vực theo phân công của Thủ tướng Chính phủ và chỉ đạo của Chính phủ","Các vấn đề thuộc phạm vi quản lý nhà nước về ngành, lĩnh vực theo phân công của Chính phủ và chỉ đạo của Thủ tướng Chính phủ","Các vấn đề thuộc phạm vi quản lý nhà nước về ngành, lĩnh vực theo phân công của Quốc hội và chỉ đạo của Chủ tịch nước Luật TCCP 2025 Irung 55","Các vấn đề thuộc phạm vi quản lý nhà nước của địa phương theo phân công của Chính phủ và chỉ đạo của Thủ tướng Chính phủ"],c:1},{id:"vb05-128",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Điều 17; Điều 18: Điều 19: Điều 20 Luật Tổ chức Chính phủ năm 2025.",gt:"Tư cách thành viên Chính phủ gắn với quyết định tập thể; tư cách người đứng đầu Bộ gắn với lãnh đạo và trách nhiệm cá nhân về mọi mặt công tác của Bộ.",mn:'Nhớ cụm "Thành viên ~ tập thể; đứng đầu - cá nhân”: thành viên thì ban bạc chung, đứng đầu thì từ chịu trách nhiệm, như dự họp hội đồng khác với điều hành phong của mình.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây ĐÚNG về sự khác nhau giữa hai tư cách của Bộ trưởng, Thủ trưởng cơ quan ngang Bộ?",o:["Là thành viên Chính phủ thì cũng tập thể quyết định công việc chung; là người đứng đầu Bộ thì lãnh đạo và chịu trách nhiệm cá nhân về mọi mặt công tác của Bộ","Là thành viên Chính phủ thì lãnh đạo và chịu trách nhiệm cá nhân về mọi mặt công tác của Bộ; là người đứng đầu Bộ thì cũng tập thể quyết định công việc chung","Cả hai tư cách đều chi chịu trách nhiệm tập thể, không có trách nhiệm cá nhân đối với kết quả hoạt động của Bộ","Cả hai tư cách đều lãnh đạo, quyết định độc lập công việc của Bộ, không phải cung tập thể Chính phủ quyết định"],c:0},{id:"vb05-129",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 4 Điều 17; khoản 9 Điều 19 Luật Tổ chức Chính phủ năm 2025. Luật TCCP 2025 Trung 5b",gt:"Với tư cách thành viên Chính phủ, nhiệm vụ khác là nhiệm vụ do Thủ tướng Chính phủ ủy quyền; với tư cách người đứng đầu Bộ thì do Chính phủ, Thủ tướng giao.",mn:'Nhớ cụm "Thành viên - ủy quyền; đứng đầu - giao": ủy quyền cho tư cách thành viên, giao cho tư cách người đứng đầu Bộ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), so với nhiệm vụ khác của Bộ trưởng với tư cách người đứng đầu Bộ (do Chính phủ, Thủ tướng Chính phủ giao), nhiệm vụ, quyền hạn khác của Bộ trưởng với tư cách thành viên Chính phủ được thực hiện theo căn cứ nào?",o:["Do Chính phủ, Thủ tướng Chính phủ giao, đồng thời phải được Quốc hội thông qua trước khi thực hiện","Do Thủ tướng Chính phủ ủy quyền","Do Chủ tịch nước ủy quyền","Do Phó Thủ tướng Chính phủ giao"],c:1},{id:"vb05-130",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 4 Điều 19 Luật Tổ chức Chính phủ năm 2025.",gt:"Bộ trưởng quyết định theo thẩm quyền các vấn đề thuộc chức năng, nhiệm vụ, quyền hạn của Bộ mình là người đứng đầu; vấn đề của Chính phủ phải quyết định tập thể.",mn:'Nhớ cụm "Việc của Bộ mình thì tự quyết”: quyết định theo thẩm quyền trong phạm vi Bộ mình đứng đầu, như trường phòng quyết việc thuộc phòng mình.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), với tư cách là người đứng đầu Bộ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ quyết định theo thẩm quyền vấn đề nào dưới đây?",o:["Vấn đề thuộc chức năng, nhiệm vụ, quyền hạn của Chính phủ mà mình là thành viên","Vấn đề thuộc chức năng, nhiệm vụ, quyền hạn của các Bộ, cơ quan ngang Bộ khác","Vấn đề thuộc chức năng, nhiệm vụ, quyền hạn của Ủy ban nhân dân cấp tỉnh","Vấn đề thuộc chức năng, nhiệm vụ, quyền hạn của Bộ, cơ quan ngang Bộ mà mình là người đứng đầu"],c:3},{id:"vb05-131",s:"CHƯƠNG II - BỘ TRƯỞNG, THỦ TRƯỞNG CƠ QUAN NGANG BỘ; BỘ, CƠ QUAN NGANG BỘ, CƠ QUAN THUỘC CHÍNH PHỦ",cc:"Khoản 9 Điều 19 Luật TỔ chức Chính phủ năm 2025.",gt:"Nhiệm vụ, quyền hạn khác của Bộ trưởng với tư cách người đứng đầu Bộ do Chính phủ, Thủ tướng Chính phủ giao.",mn:'Nhớ cụm "Chính phủ, Thủ tướng giao": hai chủ thể giao việc cho Bộ trưởng là Chính phủ, Thủ tướng, như công ty mẹ và giám đỐCc giao việc cho đơn vị trực thuộc. Luật TCCP 2025 Trung 57 Phạm vi: chế độ làm việc của Chính phủ và từng thành viên (Điều 25); hình thức hoạt động (Ðiều 20); trách nhiệm tham dự phiên họp COiều 27); phiên họp của Chính phủ - điều kiện tiến hành, biểu quyết (Điều 28): thành phần mời tham dự (Điều 29); kinh phí hoạt động (Điều 30). Nhiêu so liệu cần học thuộc, Đáp án đối chiếu Luật số',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Bộ trưởng, Thủ trưởng cơ quan ngang Bộ với tư cách là người đứng đầu Bộ còn thực hiện nhiệm vụ, quyền hạn khác do [.........",o:["Thủ tướng Chính phủ và Quốc hội","Chính phủ, Thủ tướng Chính phủ","Chính phủ và Chủ tịch nước","Quốc hội, Ủy ban Thường vụ Quốc hội"],c:1},{id:"vb05-132",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 2 Điều 25 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ làm việc theo chế độ tập thể, quyết định theo đa số.",mn:'Nhớ cụm "Tập thể — đa số”: làm việc tập thể, bỏ phiếu thì đa số tháng, như hợp lớp biểu quyết theo số đông.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), về chế độ làm việc của Chính phủ, Chính phủ làm việc theo chế độ nào và quyết định các vấn đề theo nguyên tắc nào?",o:["Thủ trưởng, Thủ tướng quyết định","Tập thể, quyết định theo nhất trí","Cá nhân, quyết định theo đa số","Tập thể, quyết định theo đa số"],c:3},{id:"vb05-133",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản Ì Điều 25 Luật Tổ chức Chính phủ năm 2025.",gt:"Chế độ làm việc dựa trên việc phân định rõ chức năng, nhiệm vụ, quyền hạn và đề cao trách nhiệm của Thủ tướng, từng thành viên Chính phủ.",mn:'Nhớ cụm "Rõ chức năng - nhiệm vụ = quyền hạn”: ba vêu tổ chức năng, nhiệm vụ, quyền hạn, như bản mô tả công việc nêu rõ vai trò của từng người.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), chế độ làm việc của Chính phủ, các thành viên Chính phủ được thực hiện trên cơ sở phân định rõ [........ ] và đề cao trách nhiệm của Thủ tướng Chính phủ, từng thành viên Chính phủ.",o:["chức năng, nhiệm vụ, quyền hạn","chức năng, thẩm quyền, trình tự","nhiệm vụ, quyền hạn, nguồn lực","quyền hạn, trách nhiệm, tổ chức bộ máy"],c:0},{id:"vb05-134",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 3 Điều 25 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ ban hành Quy chế làm việc của Chính phủ, phù hợp với chế độ làm việc tập thể.",mn:'Nhớ cụm "Quy chế của Chính phủ do Chính phủ ban hành”: Chính phù tự ban hành quy chế làm việc của mình, như tổ chức từ ban hành nội quy nội bộ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Chính phủ làm việc theo chế độ tập thể, quyết định theo đa số và thực hiện chế độ làm việc trên cơ sở phân định rõ trách nhiệm của từng thành viên. Chủ thể nào ban hành Quy chế làm việc của Chính phủ?",o:["Thủ tướng Chính phủ ban hành sau khi có ý kiến thống nhất của Ủy ban Thường vụ Quốc hội và Chủ tịch nước Luật 1ICCP 2025 Irongq 58","Quốc hội","Chính phủ","Văn phòng Chính phủ"],c:2},{id:"vb05-135",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoán I Điều 26 Luật TỔ chức Chính phủ năm 2025.",gt:"Chính phủ họp thường kỳ mỗi tháng một phiên; các cuộc họp chuyên đề, đột xuất được tổ chức khi có quyết định hoặc yêu cầu của các chủ thể có thẩm quyền.",mn:'Nhớ cụm "Tháng một phiên”: họp thường kỳ mỗi tháng một phiên, như giao ban hằng tháng của cơ quan.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Chính phủ họp thường kỳ [......... |; họp chuyên đề, họp để giải quyết công việc phát sinh đột xuất theo quyết định của Thủ tướng Chính phủ, theo yêu cầu của Chủ tịch nước hoặc của ít nhất một phần ba tổng sốõ thành viên Chính phủ.",o:["mỗi quý một phiên","hai tháng một phiên","mỗi tháng một phiên","mỗi tuần một phiên"],c:2},{id:"vb05-136",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoán Ì Điều 26 Luật TỔ chức Chính phủ năm 2025.",gt:"Phiên họp chuyên đề, đột xuất theo quyết định của Thủ tướng, yêu cầu của Chủ tịch nước hoặc ít nhất một phần ba tổng số thành viên Chính phủ; Ủy ban Thường vụ Quốc hội không có quyền này. Luật TCCP 2025 Irong 59",mn:'Nhớ cụm "Thủ tướng — Chủ tịch nước — một phần ba”: ba nguồn đề nghị hợp đột xuất, không có Ủy ban Thường vụ Quốc hội. như muốn hợp khẩn thì chỉ người đứng đầu, cấp trên trực tiếp hoặc một phần ba thành viên mọi triệu tập được.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Chính phủ họp chuyên đề hoặc họp để giải quyết công việc phát sinh đột xuất. Chủ thể nào sau đây KHÔNG thuộc nhóm chủ thể có thẩm quyền quyết định hoặc yêu cầu Chính phủ tiến hành các phiên họp này?",o:["Ủy ban Thường vụ Quốc hội yêu cầu Chính phủ họp chuyên đề, họp đột xuất","Thủ tướng Chính phủ quyết định việc họp chuyên đề, họp đột xuất của Chính phủ","Chủ tịch nước yêu cầu Chính phủ họp chuyên đề, họp đột xuất","Ít nhất một phần ba tổng số thành viên Chính phủ yêu cầu họp chuyên đề, họp đột xuất"],c:0},{id:"vb05-137",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 2 Điều 26 Luật Tổ chức Chính phủ năm 2025.",gt:"Khi Chính phủ không họp, Thủ tướng quyết định gửi lấy ý kiến các thành viên Chính phủ bằng văn bản để vận bảo đảm tính tập thể.",mn:'Nhớ cụm "Không họp thì lấy ý kiến văn bản”: thấy cuộc họp bằng phiếu lấy ý kiến bằng văn bản, như hội ý kiến qua email khi không thể họp trực tiếp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong trường hợp Chính phủ không tổ chức phiên họp mà vẫn cần xem xét, quyết định một vấn đề thuộc thẩm quyền, Thủ tướng Chính phủ giải quyết công việc theo cách nào dưới đây?",o:["Thủ tướng Chính phủ tự quyết định sau khi tham khảo ý kiến Văn phòng Chính phủ","Thủ tướng Chính phủ quyết định gửi lấy ý kiến Ủy ban Thường vụ Quốc hội bằng văn bản","Thủ tướng Chính phủ quyết định gửi lấy ý kiến của các thành viên Chính phủ bằng văn bản","Thủ tướng Chính phủ ủy quyền cho Phó Thủ tướng Chính phủ quyết định thay Chính phủ"],c:2},{id:"vb05-138",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoản 3 Điều 2Ð Luật TỔ chức Chính phủ năm 2025.",gt:"Khi ban hành quy định thực hiện chính sách dân tộc, Chính phủ phải lấy ý kiến của Hội đồng Dân tộc của Quốc hội.",mn:'Nhớ cụm "Chính sách dân tộc - Hội đồng Dân tộc”: nội dung nào thì hội cơ quan đó, chính sách dân tộc hói Hội đồng Dân tộc, như hội chuyên gia đúng lĩnh vực.',t:"m",q:"Trường hợp Chính phủ chuẩn bị ban hành quy định thực hiện chính sách dân tộc, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Chính phủ phải lấy ý kiến của cơ quan nào trước khi ban hành?",o:["Ủy ban Thường vụ Quốc hội và Ủy ban trung ương Mặt trận Tổ quốc Việt Nam bằng một văn bản góp ý chung","Chủ tịch nước","Ủy ban Thường vụ Quốc hội","Hội đồng Dân tộc của Quốc hội"],c:3},{id:"vb05-139",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 4 Điều 26 Luật Tổ chức Chính phủ năm 2025.",gt:"Đổi mới hình thức hoạt động của Chính phủ gắn với cải cách thủ tục hành chính, bảo đảm tính linh hoạt, hiệu quả và xây dựng Chính phủ điện tử, Chính phủ s6.",mn:'Nhớ cụm "Điện tử rồi tới số": Chính phủ điện tử, Chính phủ số, như chuyển từ giấy tờ sang làm việc trên nền tảng số.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Đổi mới hình thức hoạt động của Chính phủ gắn với đẩy mạnh cải cách thủ tục hành chính, bảo đảm tính linh hoạt, hiệu quả và xây dựng [........ L Luật 1CCP 2025 1rung 6U",o:["Chính phủ điện tử, kinh tế số","Chính phủ số, xã hội số","hạ tầng số, dữ liệu số","Chính phủ điện tử, Chính phủ số"],c:3},{id:"vb05-140",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoản 1 Điều 27 Luật Tổ chức Chính phủ năm 2025.",gt:"Thành viên Chính phủ vắng mặt toàn bộ hoặc một phần thời gian phiên họp thì phải được Thủ tướng Chính phù đồng ý.",mn:'Nhớ cụm "Xin phép người chủ trì”: người chủ trì họp là Thủ tướng nên phải xin Thủ tướng đồng ý, như xin phép người chủ tọa khi cần vắng mặt.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), thành viên Chính phủ có trách nhiệm tham dự phiên họp của Chính phủ. Trường hợp thành viên Chính phủ căn vắng mặt trong phiên họp hoặc vắng mặt một số thời gian của phiên họp thì phải thực hiện theo cách nào?",o:["Phải được tập thể Chính phủ đồng ý bằng hình thức biểu quyết","Phải được Chủ tịch nước đồng ý theo đề nghị của Bộ trưởng","Phải được Thủ tướng Chính phủ đồng ý trước khi vắng mặt","Phải được Chánh Văn phòng Chính phủ đồng ý và thông báo cho các thành viên khác"],c:2},{id:"vb05-141",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoán I Điều 27 Luật Tổ chức Chính phủ năm 2025. Luật TCCP 2025 Trong 61",gt:"Thủ tướng có thể cho phép thành viên Chính phủ vắng mặt và được cử cấp phó tham dự phiên họp thay.",mn:'Nhớ cụm "Thủ tướng cho phép - cấp phó dự thay”: vắng mặt phải được Thủ tướng cho phép, người thay là cấp phó, như trường phòng di vắng thì phó phòng dự họp thay.',t:"m",q:"Trường hợp Bộ trưởng Bộ X không thể dự một phiên họp của Chính phủ vị công tác đột xuất, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nếu muốn có người của Bộ tham dự thay thì thực hiện như thế nào?",o:["Chánh Văn phòng của Bộ đó được cử tham dự, nếu Thủ tướng Chính phủ cho phép vắng mặt","Chủ tịch Ủy ban nhân dân cấp tỉnh được cử tham dự, nếu Thủ tướng Chính phủ cho phép vắng mặt","Cấp phó của thành viên Chính phủ đó được cử tham dự, nếu Chủ tịch nước cho phép vắng mặt","Cấp phó của thành viên Chính phủ đó được cử tham dự thay, nếu Thủ tướng Chính phủ cho phép vắng mặt"],c:3},{id:"vb05-142",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 2 và khoản 3 Điều 27 Luật Tổ chức Chính phủ năm 2025,",gt:"Người tham dự phiên họp không phải là thành viên Chính phủ có quyền phát biểu ý kiến nhưng không có quyền biểu quyết; Chủ tịch Ủy ban nhân dân cấp tỉnh được mời khi cần thiết.",mn:'Nhớ cụm "Được mời thì nội, không bỏ phiếu”: khách mới phát biểu được, biểu quyết không, như khách dự họp có quyền góp ý nhưng không có phiếu.',t:"m",q:"Trường hợp Chủ tịch Ủy ban nhân dân tỉnh A được mời tham dự phiên họp của Chính phủ khi cần thiết, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây KHÔNG đúng về người tham dự phiên họp không phải là thành viên Chính phủ?",o:["Có quyền phát biểu ý kiến tại phiên họp của Chính phủ về nội dung được mời tham dự","Không có quyền biểu quyết tại phiên họp của Chính phủ dự được mời tham dự","Có quyền biểu quyết như thành viên Chính phủ đối với vấn đề liên quan đến địa phương mình","Được mời tham dự phiên họp của Chính phủ khi Chính phủ thấy cần thiết"],c:2},{id:"vb05-143",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoán! Điều 28 Luật TỔ chức € hình phụ năm 2025,",gt:"Phiên họp chỉ được tiến hành khi có ít nhất hai phần ba tổng số thành viên Chính phủ tham dự; con quyết định thì căn quá nửa tổng số thành viên tán thành.",mn:'Nhớ cụm "Họp: hai phần ba; quyết: quá nửa”: số dự họp hai phần ba, số tán thành quá nửa, như phải đủ người mới họp, rồi mọi biểu quyết.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Phiên họp của Chính phủ chỉ được tiến hành khi có [........ ] tổng số thành viên Chính phủ tham dự.",o:["quá nửa","ít nhất ba phần tư","ít nhất một phần ba","ít nhất hai phần ba"],c:3},{id:"vb05-144",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoún 3 Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Quyết định của Chính phủ phải được quá nửa tổng số thành viên Chính phủ biểu quyết tán thành; mức này tính trên tổng số thành viên, không tính trên số thành viên có mặt.",mn:'Nhớ cụm "Quá nửa của tổng số": mốc tính trên tổng số thành viên, không phải số người có mặt, như tính đa số trên tổng số cử tri chứ không tính trên số người dến họp.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), phiên họp của Chính phủ đã đủ số thành viên tham dự theo quy định để tiến hành. Luật 1CCP 2025 rung b2 Để một quyết định của Chính phủ được thông qua, phải có số thành viên biểu quyết tán thành ở mức nào?",o:["Ít nhất hai phần ba tổng số thành viên Chính phủ biểu quyết tán thành","Quá nửa tổng số thành viên Chính phủ biểu quyết tán thành","Quá nửa số thành viên Chính phủ có mặt tại phiên họp biểu quyết tán thành","Ít nhất ba phần tư tổng số thành viên Chính phủ biểu quyết tán thành"],c:1},{id:"vb05-145",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 3 Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Khi biểu quyết ngang nhau thì thực hiện theo ý kiến mà Thủ tướng Chính phủ đã biểu quyết.",mn:'Nhớ cụm "Hòa phiếu - theo Thủ tướng": hòa thi theo phía Thủ tướng dã bỏ phiếu, như lá phiếu của người chủ trì quyết định khi hai bên bằng nhau.',t:"m",q:"Trường hợp biểu quyết tại phiên họp của Chính phủ về một quyết định mà số thành viên tán thành và không tán thành ngang nhau, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), vấn đề được xử lý như thế nào?",o:["Coi như chưa thông qua, Thủ tướng Chính phủ báo cáo Ủy ban Thường vụ Quốc hội để xin ý kiến trước khi quyết định lại","Hoãn sang phiên họp sau","Thực hiện theo ý kiến Thủ tướng đã biểu quyết","Biểu quyết lại ngay tại phiên họp"],c:2},{id:"vb05-146",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 2 Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Nội dung phiên họp do Thủ tướng Chính phủ đề nghị và thông báo đến các thành viên Chính phủ; không giao cho chủ thể khác thực hiện thay.",mn:'Nhớ cụm "Thủ tướng đề nghị và thông báo”: một người làm cả hai việc, như người chủ trì cuộc họp vừa đặt chương trình vừa gửi giấy mới.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trước mỗi phiên họp, nội dung phiên họp của Chính phủ cần được xác định và thông báo để các thành viên chuẩn bị. Chủ thể nào đề nghị và thông báo nội dung phiên họp đến các thành viên Chính phủ?",o:["Bộ trưởng, Chủ nhiệm Văn phòng Chính phủ đề nghị nội dung phiên họp và thông báo đến các thành viên Chính phủ","Thủ tướng Chính phủ đề nghị nội dung phiên họp và thông báo đến các thành viên Chính phủ","Thủ tướng Chính phủ đề nghị nội dung phiên họp, còn Phó Thủ tướng Chính phủ thông báo đến các thành viên","Chủ tịch nước đề nghị nội dung phiên họp và thông báo đến các thành viên Chính phủ Luáạt TCCP 2025 Trong 6.3"],c:1},{id:"vb05-147",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 1 Điều 29 Luật Tổ chức Chính phủ năm 2025.",gt:'Chủ tịch nước có quyền tham dự phiên họp của Chính phủ; con Chủ tịch Hội đồng Dân tộc, lãnh đạo Mặt trận Tổ quốc và tổ chức chính trị - xã hội được Chính phủ mời trong các trường hợp luật định. $® Miẹo nhớ: Nhớ cụm "Chủ tịch nước có quyền, người khác được mời": Chủ tịch nước tham dự theo quyền, còn các chủ thể khác phải được mời, như chủ nhà tư vào còn khách thì phải có lời mới.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), trong số các chủ thể sau, chủ thể nào có quyền tham dự phiên họp của Chính phủ mà không cần chờ được Chính phủ mời?",o:["Chủ tịch Hội đồng Dân tộc của Quốc hội, trong các phiên họp bàn về chính sách kinh tế - xã hội","Chủ tịch nước","Chủ tịch Quốc hội","Chánh án Tòa án nhân dân tối cao"],c:1},{id:"vb05-148",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 2 Điều 29 Luật Tổ chức Chính phủ năm 2025.",gt:"Chủ tịch Hội đồng Dân tộc của Quốc hội được mời tham dự phiên họp khi bàn về việc thực hiện chính sách dân tộc.",mn:'Nhớ cụm "Hội đồng Dân tộc - chính sách dân tộc”: tên cơ quan gắn với nội dung hợp, như mời đúng chuyên gia theo đúng chủ đề.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), Chính phủ mời Chủ tịch Hội đồng Dân tộc của Quốc hội tham dự phiên họp của Chính phủ trong trường hợp nào dưới đây?",o:["Khi bàn về chính sách dân tộc","Khi bàn về chính sách quốc phòng, an ninh","Khi bàn về dự toán ngân sách nhà nước","Khi bàn về chính sách đối ngoại"],c:0},{id:"vb05-149",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoản 2 Điều 29 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ mời Chủ tịch Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và người đứng đầu cơ quan trung ương của tổ chức chính trị - xã hội khi bàn các vấn đề có liên quan.",mn:'Nhớ cụm "Liên quan thì mỗi": nội dung có liên quan thì mời tham dự, như mời đại diện bên liên quan khi bàn việc của họ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), Chính phủ mời Chủ tịch Ủy ban trung ương Mặt trận Tổ quốc Việt Nam và người đứng đầu cơ quan trung ương của tổ chức chính trị - xã hội tham dự phiên họp của Chính phủ trong trường hợp nào? Luật TCCP 2025 Trung bđ",o:["Khi bàn về ngân sách nhà nước hoặc về nhân sự cấp cao của Nhà nước và có văn bản mới của Chủ tịch nước","Khi bàn các vấn đề có liên quan","Khi hợp chuyên đề theo yêu cầu của Chủ tịch nước","Khi bàn về chính sách dân tộc"],c:1},{id:"vb05-150",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Diện 30 Luật Tổ chức Chính phủ năm 2025,",gt:"Kinh phí hoạt động của Chính phủ do Quốc hội quyết định từ ngân sách nhà nước.",mn:'Nhớ cụm "Quốc hội cấp từ ngân sách”: Quốc hội quyết định, nguồn ngân sách nhà nước, như hội đồng quản trị duyệt ngân sách cho ban điều hành.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), kinh phí hoạt động của Chính phủ do cơ quan nào quyết định và được lấy từ nguồn nào?",o:["Quốc hội, từ quỹ dự phòng ngân sách","Chính phủ, từ ngân sách nhà nước","Quốc hội, từ ngân sách nhà nước","Chủ tịch nước, từ ngân sách nhà nước"],c:2},{id:"vb05-151",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"Khoản 1 Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Điều kiện tiến hành phiên họp là ít nhất hai phần ba tổng số thành viên; hai phần ba của 25 là khoảng 16,7 nên cần ít nhất 17 thành viên. 106 thành viên là chưa đủ. Luáaạt TCCP 2025 Irong 65",mn:'Nhớ cụm "Hai phần ba làm tròn lên”: 25 thành viên thì cán 17 người, như cần đủ hai phần ba số người nên phải làm tròn lên chủ không làm tròn xuống.',t:"m",q:"Giá sử Chính phủ có 25 thành viên và một phiên họp của Chính phủ có 16 thành viên tham dự, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), phiên họp này có đủ điều kiện để tiến hành hay không?",o:["Đủ điều kiện, vì 16 thành viên đa là quá nửa tổng số 25 thành viên Chính phủ","Đủ điều kiện, vì chỉ cần ít nhất một phần ba tổng số thành viên Chính phủ tham dự","Chưa đủ điều kiện, vị phải có ít nhất ba phân tư tổng số 25 thành viên, tức ít nhất 19 thành viên","Chưa đủ điều kiện, vị phải có ít nhất 17 thành viên tham dự, tức ít nhất hai phần ba tổng số 25 thành viên"],c:3},{id:"vb05-152",s:"CHƯƠNG IV - CHẾ ĐỘ LÀM VIỆC CỦÚA CHÍNH PHỦ 622025-QHI5.",cc:"khoản 3 Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Biểu quyết ngang nhau thì thực hiện theo ý kiến mà Thủ tướng đã biểu quyết; vi Thủ tướng biểu quyết không tán thành nền vấn đề không được thông qua.",mn:"Nhớ cụm “Theo phía Thủ tướng đứng”: Thủ tướng đúng về phía nào thì theo phía đó, như lá phiếu quyết định của người chủ tọa khi hòa phiếu. Luật 1CCP 2025 1rung 6b Phạm vi: hiệu lực thi hành, văn bản bị thay thế (Điều 31): điều khoản chuyển tiếp (Điều 32): và các cầu tổng hợp, so sánh, điểm mới của Luật. Đốẹp án đối chiếu Luật số",t:"m",q:"Trường hợp tại phiên họp của Chính phủ, một vấn đề được biểu quyết với số phiếu tán thành và không tán thành bằng nhau, trong đó Thủ tướng Chính phủ đã biểu quyết không tán thành, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), kết quả được xử lý như thế nào?",o:["Vấn đề được thông qua","Thực hiện theo ý kiến không tán thành","Biểu quyết lại tại phiên sau","Do Chủ tịch nước quyết định"],c:1},{id:"vb05-153",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản 1 Điều 31 Luật TỔ chức Chính phủ năm 2025.",gt:"Luật có hiệu lực thi hành từ ngày 01 tháng 3 năm 2025; ngày 18 tháng 02 năm 2025 là ngày Quốc hội thông qua Luật.",mn:'Nhớ cụm "Thông qua tháng 2, hiệu lực tháng 3": thông qua ngày 18/02, có hiệu lực 01/3/2025, như ký hợp đồng trước rồi tháng sau mỗi bắt đầu thực hiện.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH13), Luật Tổ chức Chính phủ năm 2025 có hiệu lực thi hành từ [......... |, đồng thời Luật Tổ chức Chính phủ năm 2015 và các luật sửa đổi, bổ sung hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành.",o:["ngày 18 tháng 02 năm 2025","ngày 01 tháng 7 năm 2025","ngày 01 tháng 01 năm 2026","ngày 01 tháng 3 năm 2025"],c:3},{id:"vb05-154",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản 2 Điều 31 Luật Tổ chức Chính phủ năm 2025.",gt:"Luật Tổ chức Chính phủ năm 2015 đã được sửa đổi, bổ sung năm 2019 và năm 2023 hết hiệu lực kể từ ngày Luật năm 2025 có hiệu lực thi hành.",mn:'Nhớ cụm "Luật cũ cùng hai lần sửa đều hết hiệu lực”: gồm luật gốc 2015 và hai lần sửa 2019, 2023, như thay cả bản gốc và các phụ lục bằng bản mới.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), kể từ ngày Luật này có hiệu lực thi hành, văn bản pháp luật nào dưới đây hết hiệu lực?",o:["Luật Tổ chức Chính phủ năm 2015 đã được sửa đổi, bổ sung năm 2019, còn phần sửa đổi, bổ sung năm 2023 tiếp tục có hiệu lực","Luật Tổ chức Chính phủ năm 2015 đã được sửa đổi, bổ sung năm 2019 và năm 2023, hết hiệu lực từ ngày 01 tháng 01 năm 2026","Luật Tổ chức Chính phủ năm 2015 mà chưa tính các luật sửa đổi, bổ sung năm 2019 và năm 2023","Luật Tổ chức Chính phủ năm 2015 đã được sửa đổi, bổ sung năm 2019 và năm 2023"],c:3},{id:"vb05-155",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoán I Điều 32 Luật Tổ chức Chính phủ năm 2025.",gt:"Thời hạn điều chỉnh thống nhất các văn bản chưa phù hợp là 02 năm kể từ ngày Luật có hiệu lực thi hành.",mn:'Nhớ cụm "Hai năm để rà soát": 02 năm để các luật, nghị quyết, pháp lệnh liên quan điều chỉnh, như thời gian chuyển tiếp để mọi nơi kịp thay đổi.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15): Trường hợp luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội quy định về nhiệm vụ, quyền hạn của Chính phủ, Thủ tướng Luật TCCP 2025 Trung 67 Chính phủ, Bộ trưởng, Thủ trưởng cơ quan ngang Bộ chưa phù hợp với Luật này thì phải điều chỉnh thống nhất trong thời hạn |[......... |] kể từ ngày Luật này có hiệu lực thi hành.",o:["01 năm","03năm","02năm","06 tháng"],c:2},{id:"vb05-156",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản 2 Điều 32 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ định kỳ báo cáo Ủy ban Thường vụ Quốc hội; nếu liên quan đến luật, nghị quyết của Quốc hội thì báo cáo Quốc hội tại kỳ họp gần nhất.",mn:'Nhớ cụm "Pháp lệnh báo Thường vụ, luật báo Quốc hội”: văn bản cấp nào thì báo cáo cơ quan cấp đó, như báo cáo đúng cấp có thẩm quyền phê duyệt.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), trong thời gian luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội chưa được sửa đổi theo thời hạn chuyển tiếp, để bảo đảm giải quyết việc phân quyền, phân cấp đối với một số lĩnh vực ưu tiên, cấp bách, Chính phủ ban hành văn bản quy phạm pháp luật điều chỉnh. Việc báo cáo về văn bản này được thực hiện như thế nào?",o:["Báo cáo định kỳ Chủ tịch nước; trường hợp liên quan đến luật, nghị quyết của Quốc hội thì báo cáo Quốc hội tại kỳ họp gần nhất","Báo cáo định kỳ Ủy ban Thường vụ Quốc hội; trường hợp liên quan đến luật, nghị quyết của Quốc hội thì báo cáo Quốc hội tại kỳ họp gần nhất","Báo cáo định kỳ Ủy ban Thường vụ Quốc hội; trường hợp liên quan đến luật, nghị quyết của Quốc hội thì báo cáo Chủ tịch nước tại phiên họp gần nhất","Báo cáo định kỳ Quốc hội; trường hợp liên quan đến pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội thì báo cáo Ủy ban Thường vụ Quốc hội"],c:1},{id:"vb05-157",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Điều 7: Điều 8; Điều 9 Luật Tổ chức Chính phủ năm 2025.",gt:"Phân quyền do Quốc hội quy định; phân cấp là giao thực hiện liên tục, thường xuyên; ủy quyền là giao thực hiện trong khoảng thời gian xác định và bên được ủy quyền không được ủy quyền tiếp.",mn:"Nhớ cụm ”Quyen — Quốc hội; cấp — thường xuyên; ủy - có thời hạn”: phân quyền do Quốc hội, phân cấp làm thường xuyên, ủy quyền có thời hạn, như giao hạn, giao lâu dài và nhờ làm hộ.",t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây DỤNG khi phân biệt phân quyền, phân cấp và ủy quyền trong hệ thống cơ quan nhà nước?",o:["Phân quyền do Chính phủ quy định trong nghị định; phân cấp giao thực hiện liên tục, thường xuyên; ủy quyền giao thực hiện trong khoảng thời gian xác định","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp giao thực hiện trong khoảng thời gian xác định; ủy quyền giao thực hiện liên tục, thường xuyên Luaạt 1CCP 2025 Irung 68","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp giao thực hiện liên tục, thường xuyên; ủy quyền được ủy quyền tiếp cho cơ quan, cá nhân khác","Phân quyền do Quốc hội quy định trong luật, nghị quyết; phân cấp giao thực hiện liên tục, thường xuyên; ủy quyền giao thực hiện trong khoảng thời gian xác định"],c:3},{id:"vb05-158",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Điều 7; Điều 8; Điều 9: Điều 21: Điều 25; Điều 26; Điều 28 Luật Tổ chức Chính phủ năm 2025.",gt:"Chính phủ họp thường kỳ mỗi tháng một phiên và làm việc theo chế độ tập thể, quyết định theo đa số: nội dung nêu trong phương án đúng là sai ở cả hai điểm.",mn:'Nhớ cụm "Tháng một phiên, tập thể — đa số”: sai khi nội mỗi tuần hoặc chế độ thủ trưởng, như hợp giao ban hằng tháng và quyết định bằng biểu quyết.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây KHÔNG đúng về các nội dung cơ bản của Luật?",o:["Luật quy định rõ cơ chế phân quyền, phân cấp, ủy quyền trong hệ thống cơ quan nhà nước và nguyên tắc phân định thẩm quyền","Khi biểu quyết ngang nhau tại phiên họp Chính phủ thì thực hiện theo ý kiến mà Thủ tướng Chính phủ đã biểu quyết","Chính phủ họp thường kỳ mỗi tuần một phiên và làm việc theo chế độ thủ trưởng, quyết định theo ý kiến Thủ tướng Chính phủ","Số lượng Thứ trưởng không quá 05, riêng Bộ Quốc phòng, Bộ Công an, Bộ Ngoại giao không quá 06"],c:2},{id:"vb05-159",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"(Điều II; Điều 2b: Điều 28 Luật Tổ chức C hính phụ năm 2025,",gt:"Chính phủ họp mỗi tháng một phiên: phiên họp cần ít nhất hai phần ba thành viên dự; quyết định cần quá nửa thành viên tán thành; báo cáo công tác với Quốc hội, Ủy ban Thường vụ Quốc hội, Chủ tịch nước một năm hai lần.",mn:"Nhớ dãy “Tháng 1 — 2/3~ quá nửa -— ] năm 2 lần”: tháng một phiên, hai phần ba để họp, quá nửa để quyết, năm hai lần báo cáo, như một dãy số cơ định đọc theo thứ tự.",t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây ĐÚNG và đầy đủ nhất về các còn số trong hoạt động của Chính phủ?",o:["Họp thường kỳ mỗi tháng một phiên; phiên họp tiến hành khi có quá nửa tổng số thành viên; quyết định cần ít nhất hai phần ba tổng số thành viên tán thành; báo cáo công tác một năm hai lần","Họp thường kỳ mỗi quý một phiên; phiên họp tiến hành khi có ít nhất hai phần ba tổng số thành viên; quyết định cần quá nửa tổng số thành viên tán thành; báo cáo công tác một năm hai lần Luật TCCP 2025 Trong 69","Họp thường kỳ mỗi tháng một phiên; phiên họp tiến hành khi có ít nhất hai phần ba tổng số thành viên; quyết định cần quá nửa tổng số thành viên tán thành; báo cáo công tác mỗi năm một lần","Họp thường kỳ mỗi tháng một phiên; phiên họp tiến hành khi có ít nhất hai phần ba tổng số thành viên; quyết định cần quá nửa tổng số thành viên tán thành; báo cáo công tác một năm hai lần"],c:3},{id:"vb05-160",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản Ì Điều 4 luật TỔ chức Chính phủ năm 2023.",gt:"Thủ tướng Chính phủ do Quốc hội bầu trong số các đại biểu Quốc hội theo đề nghị của Chủ tịch nước.",mn:'Nhớ cụm "Chủ tịch nước đề nghị, Quốc hội bầu”: Chủ tịch nước đề nghị, Quốc hội bầu, như một bên giới thiệu và một bên quyết định.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), Thủ tướng Chính phủ do Quốc hội bầu trong số các đại biểu Quốc hội theo đề nghị NI ], và là người đứng đầu Chính phủ và hệ thống hành chính nhà nước.",o:["Chủ tịch Quốc hội","Ủy ban Thường vụ Quốc hội","Chủ tịch nước","Thủ tướng Chính phủ nhiệm kỳ trước"],c:2},{id:"vb05-161",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản 1 và khoản 2 Điều 2 Luật TỔ chức © hình phủ năm 2025.",gt:"Việc thành lập, bãi bỏ Bộ, cơ quan ngang Bộ do Chính phủ trình Quốc hội quyết định; cơ cấu số lượng thành viên Chính phủ cũng do Thủ tướng trình Quốc hội quyết định. Luật FCCP 2025 lrang -U",mn:'Nhớ cụm "Cơ cấu và số lượng — Quốc hội quyết”: hai việc về bộ máy Chính phủ đều do Quốc hội quyết, như hội đồng cao nhất quyết định khung tổ chức.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), việc thành lập, bãi bỏ Bộ, cơ quan ngang Bộ do Chính phủ trình [......... ] quyết định, còn cơ cấu số lượng thành viên Chính phủ do Thủ tướng Chính phủ trình cơ quan đó quyết định.",o:["Ủy ban Thường vụ Quốc hội","Chủ tịch nước","Quốc hội","Thủ tướng Chính phủ"],c:2},{id:"vb05-162",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Điều 25; Điều 206; Điều 28 Luật Tổ chức Chính nhủ năm 2()25.",gt:"Quyết định của Chính phủ chỉ cần quá nửa tổng số thành viên tán thành; mức hai phần ba là điều kiện để tiến hành phiên họp.",mn:'Nhớ cụm "Hợp hai phần ba, quyết quá nửa”: dùng lẫn hai mục, hai phần ba đế họp, quá nửa để quyết.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây KHÔNG đúng về chế độ làm việc và phiên họp của Chính phủ?",o:["Quyết định của Chính phủ phải được ít nhất hai phần ba tổng số thành viên Chính phủ biểu quyết tán thành","Chính phủ làm việc theo chế độ tập thể, quyết định theo đa số các thành viên Chính phủ","Phiên họp của Chính phủ được tiến hành khi có ít nhất hai phần ba tổng số thành viên dự","Chính phủ họp thường kỳ mỗi tháng một phiên và hợp chuyên đề, đột xuất khi có yêu cầu"],c:0},{id:"vb05-163",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Điểm c khoản 4 Điều 13 Luật Tổ chức Chính phủ năm 2025.",gt:"Thủ tướng chỉ đạo, điều hòa, phối hợp hoạt động giữa các thành viên Chính phủ và quyết định các vấn đề khi còn có ý kiến khác nhau giữa các Bộ trưởng, Thủ trưởng cơ quan ngang Bộ.",mn:'Nhớ cụm "Hai Bộ bất đông - Thủ tướng quyết”: người điều hòa, phối hợp và quyết định là Thủ tướng, như giám đốc quyết định khi hai phòng không thống nhất.',t:"m",q:"Trường hợp một nhiệm vụ liên quan đến nhiều ngành nhưng còn ý kiến khác nhau giữa hai Bộ trưởng, theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), ai có thẩm quyền quyết định các vấn đề còn ý kiến khác nhau do?",o:["Thủ tướng Chính phủ","Chính phủ họp và biểu quyết theo đa số, Thủ tướng Chính phủ chỉ chủ trì mà không quyết định vấn đề","Chủ tịch nước","Quốc hội"],c:0},{id:"vb05-164",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Khoản 4 Điều ¬ Luật lô chức Chính phủ năm 2025.",gt:"Nguyên tắc là phân quyền, phân cấp hợp lý giữa Chính phủ với chính quyền địa phương, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của chính quyền địa phương.",mn:'Nhớ cụm "Phân cấp hợp lý, thống nhất văn ở Chính phủ": giao quyền nhưng vẫn quản lý thống nhất, như giao việc cho chi nhánh nhưng trụ sở văn giữ quy chế chung.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây ĐÚNG về mối quan hệ giữa Chính phủ và chính quyền địa phương trong nguyên tắc tổ chức và hoạt động của Chính phủ? Luật TCCP 2025 Trong 71",o:["Phân quyền, phân cấp giữa Chính phủ với chính quyền địa phương, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, tự chịu trách nhiệm của các Bộ, cơ quan ngang Bộ","Tập trung quyết định các vấn đề của địa phương tài Chính phủ, bảo đảm quyền quản lý thống nhất của Chính phủ và hạn chế tính chủ động, sáng tạo của chính quyền địa phương","Phân quyền, phân cấp hợp lý giữa Chính phủ với chính quyền địa phương, bảo đảm quyền quản lý thống nhất của Chính phủ và phát huy tính chủ động, sáng tạo, tự chịu trách nhiệm của chính quyền địa phương","Phân quyền, phân cấp cho chính quyền địa phương độc lập trong phạm vi được giao, Chính phủ không còn quyền quản lý thống nhất đối với chính quyền địa phương"],c:2},{id:"vb05-165",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Điều 2; Điều 22 Luật Tổ chức Chính phủ năm 2025.",gt:'Quốc hội quyết định số lượng thành viên Chính phủ và việc thành lập, bãi bỏ Bộ; con Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức từng Bộ. Luut TCCP "25 lrung ^2',mn:'Nhớ cụm "Số lượng, thành lập — Quốc hội; chức năng, cơ cấu - Chính phủ”: khủng do Quốc hội, chi tiết do Chính phủ, như hội đồng quyết định có mở phòng, giám đốc quy định nhiệm vụ phòng.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (Luật số 63/2025/QH15), nhận định nào sau đây ĐÚNG về thẩm quyền trình và quyết định trong tổ chức bộ máy của Chính phủ?",o:["Số lượng thành viên Chính phủ do Chính phủ trình Ủy ban Thường vụ Quốc hội quyết định; việc thành lập, bãi bỏ Bộ do Chính phủ trình Quốc hội quyết định; chức năng, cơ cấu của từng Bộ do Chính phủ quy định","Số lượng thành viên Chính phủ do Thủ tướng Chính phủ trình Quốc hội quyết định; việc thành lập, bãi bỏ Bộ do Chính phủ trình Quốc hội quyết định; chức năng, cơ cấu của từng Bộ do Chính phủ quy định","Số lượng thành viên Chính phủ do Thủ tướng Chính phủ trình Quốc hội quyết định; việc thành lập, bãi bỏ Bộ do Thủ tướng Chính phủ quyết định; chức năng, cơ cấu của từng Bộ do Chính phủ quy định","Số lượng thành viên Chính phủ do Thủ tướng Chính phủ trình Quốc hội quyết định; việc thành lập, bãi bỏ Bộ do Chính phủ trình Quốc hội quyết định; chức năng, cơ cấu của từng Bộ do Quốc hội quy định"],c:1},{id:"vb05-166",s:"CHƯƠNG V - ĐIỀU KHOẢN THI HÀNH VÀ PHÂN TỔNG HỢP, NÂNG CAO 63/2025/QH15.",cc:"Diện ù khoản 3 Liệu 14 Luật Tổ chức Chính phủ năm 20.25.",gt:"Sau khi được sửa đổi, bổ sung, Thủ tướng trình Chủ tịch nước quyết định việc phê chuẩn, gia nhập hoặc chấm dứt hiệu lực đối với điều ước quốc tế thuộc thẩm quyền của Chủ tịch nước; việc phê duyệt điều ước nhân danh Chính phủ thuộc thẩm quyền của Chính phủ.",mn:'Nhớ cụm "Chủ tịch nước phê chuẩn, Chính phủ phê duyệt”: điều ước của Chủ tịch nước thì phê chuẩn, gia nhập hoặc chấm dứt hiệu lực, như phân biệt phê chuẩn cấp nhà nước với phê duyệt cấp Chính phủ.',t:"m",q:"Theo Luật Tổ chức Chính phủ năm 2025 (được sửa đổi, bổ sung bởi Luật số 137/2025/QH15 - hợp nhất tại VBHN số 27/VBHN-VPQH), Thủ tướng Chính phủ trình Chủ tịch nước quyết định [........ | đối với điều ước quốc tế thuộc thẩm quyền của Chủ tịch nước.",o:["ký, phê chuẩn, chấm dứt hiệu lực","phê chuẩn, gia nhập, đàm phán","phê chuẩn, gia nhập, chấm dứt hiệu lực","phê duyệt, gia nhập, chấm dứt hiệu lực"],c:2}];export{h as default};
